quests[12735] = { id = 12735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cleansing Song", description = "Earth in Sholazar is pure.  The pillars have protected the land for centuries.\n\nWater, not as pure, it comes from outside Sholazar.... from oceans, from lakes, from rivers.  Water sometimes bring bad spirits - need to be cleansed.\n\nYou take this chime and play at Bittertide Lake, Wintergrasp River and River's Heart.  It make bad spirit angry... and then you must kill it.", completion = "Waters... cleansed.  Yes.  All is well.\n\nYou understand our way, {name}.", objectives = "Soo-nee, at the Rainspeaker Canopy, wants you to play the Cleansing Chime at Bittertide Lake, Wintergrasp River and River's Heart and slay the evil spirits that plague the waters there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12736] = { id = 12736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Song of Reflection", description = "Of course you not as smart as gorloc!  You just simple {race}.\n\nYou not without hope, though!  You show you can learn.  Maybe crystals make you smart like crystals make us smart!\n\nI teach you to play song to clear your mind.  You play song by crystals then crystals make your mind better... not as good as gorloc's but better than you have now.  Lifeblood Pillar is broken, but other pillars still good!", completion = "You see?  I can tell you smarter already.  And if not smarter... then... happier!", objectives = "Soo-nee at Rainspeaker Canopy wants you to use the Didgeridoo of Contemplation at the top of the Glimmering Pillar, the Suntouched Pillar, the Mosslight Pillar and the Skyreach Pillar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12737] = { id = 12737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Song of Fecundity", description = "The storm is a destructive force.  Storm burns trees.  Storm floods houses.\n\nBut storm can also be life force if you know right song.  In Stormwright Shelf, above Maker's Perch, you can find small dirt mounds.  They very fertile -- they carry inside a strong seed.  All they wait for is the right song.\n\nYou take this horn and play song for them.", completion = "You learn fast, {name}.  You learn that song well.  Maybe next time I teach you different song.", objectives = "Soo-nee at Rainspeaker Canopy wants you to go to the Stormwright's Shelf, northwest of the Maker's Perch, and play the Horn of Fecundity near 8 piles Soaked Fertile Dirt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12738] = { id = 12738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cry For Vengeance!", description = "The cry for vengeance must be heard, {name}. Commander Plaguefist and a company of death knights are on their way to raze the Chapel of the Crimson Flame. If there are any death knights imprisoned at the chapel, Plaguefist will get them out.\n\nYou can still catch up to them if you hurry. The chapel is due west of here.", completion = "They're only flesh and bone - no match for the Scourge.\n\nWe didn't find any of our brothers, but we did stumble upon something special.", objectives = "Report to Knight Commander Plaguefist at the Chapel of the Crimson Flame.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12739] = { id = 12739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty tauren in there that I think you'll take great pleasure in executing.", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", objectives = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Malar Bravehorn, an Argent Dawn prisoner inside the nearby prison house.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12740] = { id = 12740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parachutes for the Argent Crusade", description = "Those sky terrors are destroying my men and women! Dying from falling is a horrible way to go.\n\n{class}, you have to get these parachutes out to them! At least then they'll have a fighting chance to survive.", completion = "You're a good man, {name}. We're fortunate that you happened to stop by.\n\nStick around a while. I'm sure that we have much that a capable {class} such as yourself can do.", objectives = "Commander Falstaav at The Argent Stand has asked you to equip 10 Argent Crusaders or Argent Shieldmen out in the courtyard with parachutes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12741] = { id = 12741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strength of the Tempest", description = "Silly big-tongues think singing to the clouds give them power. Rejek show big-tongues how to get power by taking it!\n\nFar to northwest, there is large, flat area the big-tongues call 'Stormwright's Shelf.' Rejek is sure you can only get there by flying like bird.\n\nOn this shelf, Rejek has heard of mighty forces of wind and water. Kill them for their badness, then take it to the big-tongue 'Shrine of the Tempest' at shelf's western side. Rejek will await your return with ultimate power.", progress = "You bring Rejek true power of elements?", completion = "Now Rejek show cowardly big-tongues how to really use elements!", objectives = "Gather 3 Essences of the Monsoon and 3 Essences of the Storm and take them to the Shrine of the Tempest. Return to Rejek at Frenzyheart Hill with the True Power of the Tempest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12742] = { id = 12742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty human in there that I think you'll take great pleasure in executing.", progress = "How does it feel?", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", objectives = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Ellen Stanbridge, an Argent Dawn prisoner inside the nearby prison house.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12743] = { id = 12743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty night elf in there that I think you'll take great pleasure in executing.", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", objectives = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Yazmina Oakenthorn, an Argent Dawn prisoner inside the nearby prison house.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
