quests[12746] = { id = 12746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty draenei in there that I think you'll take great pleasure in executing.", progress = "How does it feel?", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", objectives = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Valok the Righteous, an Argent Dawn prisoner inside the nearby prison house.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12747] = { id = 12747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty blood elf in there that I think you'll take great pleasure in executing.", progress = "How does it feel?", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", objectives = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Lady Eonys, an Argent Dawn prisoner inside the nearby prison house.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12748] = { id = 12748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty orc in there that I think you'll take great pleasure in executing.", progress = "How does it feel?", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", objectives = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Kug Ironjaw, an Argent Dawn prisoner inside the nearby prison house.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12749] = { id = 12749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty troll in there that I think you'll take great pleasure in executing.", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", objectives = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Iggy Darktusk, an Argent Dawn prisoner inside the nearby prison house.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12750] = { id = 12750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty Forsaken in there that I think you'll take great pleasure in executing.", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", objectives = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Antoine Brack, an Argent Dawn prisoner inside the nearby prison house.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12751] = { id = 12751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sort Of Homecoming", description = "Return to Thassarian at the Scarlet Tavern and let him know that Koltira's cry for vengeance has been answered. The Chapel of the Crimson Flame will be a pile of ashes in a matter of hours.\n\nYou're one cold-blooded monster, {name}. I salute you, <brother/sister>.", completion = "Another Scourge victory! These Scarlet dogs have nowhere left to run and hide. It's only a matter of time now...", objectives = "Return to Thassarian at the Scarlet Tavern in New Avalon with news of your victory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12752] = { id = 12752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Research", description = "{name}, the Lich King plagues us with invasion.  To beat him back to his frozen throne, the Horde and Alliance must stand resolute together.  In Shattrath, in the Terrace of Light, that alliance has been struck.\n\nTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress.  He leads desperate research to end the zombie plague.  His cure is our salvation.\n\nBe swift, {name}.  Each moment passed is another innocent life lost.", sourceObjective = "Speak with Grand Apothecary Putress in the new apothecary camp at the Terrace of Light in Shattrath.{name}, the Lich King plagues us with invasion. To beat him back to his frozen throne, the Horde and Alliance must stand resolute together. In Shattrath, in the Terrace of Light, that alliance has been struck.\n\nTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress. He leads desperate research to end the zombie plague. His cure is our salvation.\n\nBe swift, {name}. Each moment passed is another innocent life lost.", sourceObjectiveStatus = "unverified-source-field" }
quests[12753] = { id = 12753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Desperate Alliance", description = "Good {name}, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion.  Only by joining our strengths can the two great cultures of Azeroth survive against his assault.\n\nIn Shattrath, in the Terrace of Light, that alliance has been struck.  To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.\n\nLight speed, {name}.", sourceObjective = "Speak with Bishop Lazaril in the new Alliance camp at the Terrace of Light in Shattrath.Good {name}, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion. Only by joining our strengths can the two great cultures of Azeroth survive against his assault.\n\nIn Shattrath, in the Terrace of Light, that alliance has been struck. To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.\n\nLight speed, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12754] = { id = 12754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ambush At The Overlook", description = "While you were out burning churches and murdering vermin, I've been busy formulating a plan.\n\nThe Scarlet courier is scheduled to pass by the Scarlet Overlook within the hour. The roads by the overlook are wide open and swarming with Crusaders. Use this makeshift cover to hide at the overlook and wait for the Scarlet Courier to pass. When he's close enough, strike with all your fury! Cut him down and take his belongings - including his clothes!\n\nThe overlook is 200 paces east of here.", progress = "You're going to miss the courier and then I'm going to be forced to kill you. By forced I mean I will take great pleasure in ending your life.\n\nHURRY UP!", completion = "<Orbaz reads the message.>\n\nThe armies of Hearthglen and Tirisfal will be marching into a massacre.\n\n<Orbaz smiles.>\n\nNow for the second part of the plan. You're going to deliver this message right into the hands of High General Abbendis. That's what the clothes are for...", objectives = "Orbaz Bloodbane at the Scarlet Tavern in New Avalon has ordered you to kill the Scarlet Courier and retrieve the Scarlet Courier's Belongings and the Scarlet Courier's Message.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12755] = { id = 12755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Meeting With Fate", description = "This message must reach Abbendis. We do not want to draw their suspicion. They must continue under the assumption that everything is going as they planned.\n\nYou will don the Scarlet courier's clothes and with the help of some dark magic, take on the form of the courier.\n\nAbbendis is at King's Harbor, southeast of the Scarlet Overlook. Drop off the message and get as much information out of her as you can. She will tell us what we need to know about the \"Crimson Dawn.\"", progress = "Where have you been? You are two hours late. We were about to send a courier out to the High Commander.", completion = "<High General Abbendis reads the message.>\n\nDamn it! The armies of Hearthglen and Tirisfal must not reach New Avalon! The Scourge will slaughter them all.", objectives = "Orbaz Bloodbane has commanded you to deliver the Scarlet Courier's Message to High General Abbendis at King's Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12756] = { id = 12756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scarlet Onslaught Emerges", description = "Listen well, courier. The Scarlet lands are lost. New Avalon and Havenshire are overrun by Scourge. The specter of death looms overhead and threatens to overtake us at any moment.\n\nReturn to Galvar with this message:\n\n\"Turn your armies around and prepare your ships for travel to the frozen wastes. When next we meet it will be in Northrend.\"\n\nGive this to Galvar.\n\n<Abbendis hands you a journal.>\n\nIt will explain everything.\n\nThe Scarlet Crusade is no more. Long live the Scarlet Onslaught!", progress = "<Orbaz laughs.>\n\nWhat is this? Some child's coloring book?", completion = "<Orbaz flips through the journal.>\n\nWhat rubbish! This is the \"Crimson Dawn?\"\n\nThey sail to their deaths! Let us turn our focus to the encroaching armies.", objectives = "Deliver The Path of Redemption to Orbaz Bloodbane at the Scarlet Tavern in New Avalon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12757] = { id = 12757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scarlet Armies Approach...", description = "We must prepare for the encroaching armies, {name}. You will take what you have discovered to Highlord Mograine at once! I will open a portal directly to Acherus. Step inside and it will transport you.\n\nGive Highlord Mograine Abbendis' journal as well. Perhaps he'll find it useful.", progress = "You did what?", completion = "You have become an instrument of doom, {class}! We will ravage these approaching armies and raise the dead as our own!", objectives = "Deliver The Path of Redemption to Highlord Darion Mograine at Acherus: The Ebon Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12758] = { id = 12758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero's Headgear", description = "Rejek hears tales of giant metal men on faraway Stormwright's Shelf. Far to northwest, outside basin's lip, you will find it.\n\nImagine Rejek using heads of giant metal men as helmet. Make Rejek unstoppable! Make Rejek mighty!\n\nYou get for Rejek, but metal head might not come off metal body easy. Maybe steal bombs from little green men and their friends at Swindlegrin's Dig near Suntouched Pillar? Use bombs to get head off metal body, then bring to Rejek.", progress = "You bring Rejek's new helmet?", completion = "Rejek sees you were successful! Now Rejek try on new war helmet.", objectives = "Get Venture Co. Explosives from any of the Venture Company units at Swindlegrin's Dig and use them to obtain a Stormwatcher's Head. Bring the Stomwatcher's Head to Rejek at Frenzyheart Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12759] = { id = 12759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tools of War", description = "Zepik tell me that you maybe the best gorloc hunter he met... other than Zepik. Still big battle to southwest - you go help.\n\nZepik keeps some of biggest, baddest traps in his stash at Kartak's Hold... told Vekgar to use them for battle, so you use them too. Go pick out any traps you want and kill lots of big-tongues.\n\nLots and lots!", completion = "You almost as good with those traps as Zepik!", objectives = "Retrieve some of Zepik's traps from his stash in Kartak's Hold. Using the traps, slaughter 50 of the nearby Sparktouched Gorlocs, and then return to Shaman Jakjek in Kartak's Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12760] = { id = 12760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secret Strength of the Frenzyheart", description = "Battle still going at Kartak hold... I think it time for you to learn big secret of Frenzyheart.\n\nWe have berries we keep from other lands we came from... they not so special on their own, but mix them with drunk drinks and they make Frenzyheart super strong. You a Frenzyheart now... it time you get to be strong too.\n\nI give some drink, then you be super strong and you go smash all the spark big-tongues.", completion = "You a fierce fighter... come back for more battle soon. Never enough good battle!", objectives = "Using the secret Frenzyheart drink, slaughter 30 of the Sparktouched Gorlocs around Kartak's Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12761] = { id = 12761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastery of the Crystals", description = "Sparktouched are still being attacked by puppy-men... we think they maybe not stop if we not make them stop. We have secret weapon though... we sent it out to Soo-met so he can use to protect all Oracles.\n\nSecret weapon is from Great Ones themselves... extra shiny crystals found inside sacred Great One temples. Be very careful... no break them.\n\nCrystals are in chest near shrine at Sparktouched Haven, in far southwest. You go use crystals to help Soo-met beat the puppy-men.", completion = "Thank you, dryskin.\n\nI hold onto these crystals here to keep us safe. Maybe you come back soon and help us more.", objectives = "Retrieve the crystal defenses at Sparktouched Haven and use them to kill 50 of the nearby Frenzyheart wolvar. When these tasks are complete, return to Lightningcaller Soo-met in Sparktouched Haven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12762] = { id = 12762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power of the Great Ones", description = "We need to do something to stop puppy-men attacking Sparktouched Haven. Jaloot brought me very special crystal that he found in River's Heart... we seen only one like it before.\n\nThe crystal not have power now, but the opened up lifeblood pillar should have energy to recharge it if you just bring it close. Once the crystal is charged, go to Sparktouched Haven in far southwest and let the crystal's energy make you big and strong.\n\nThen it time to kick some puppy-men butt.", progress = "Good to have you here to help us. Long fight.", completion = "So much energy in you... you full of the power of the Great Ones!\n\n I not lie, I little bit jealous.", objectives = "Charge the Dormant Polished Crystal at the exposed Lifeblood Pillar. Travel to Sparktouched Haven and use the power the crystal bestows to slaughter 30 of the nearby Frenzyheart wolvar, and then speak to Lightningcaller Soo-met in Sparktouched Haven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12763] = { id = 12763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shifting Priorities", description = "As pressing as our needs are here, there's news from the lands to the north that cannot be ignored.\n\nI've just received a message from the Argent Crusade. It seems that scourge forces are gathering there and are threatening to overrun Zul'Drak.\n\nNeedless to say, {name}, if that were to happen our struggle here would be meaningless. You must go there and aid the Crusaders in beating back the Lich King's armies.\n\nSpeak to Makki when you are ready to travel.", completion = "The Light shall prevail!", objectives = "Scout Vor'takh wants you to travel to Zul'Drak and report to Sergeant Riannah at Light's Breach.\n\nMakki Wintergale in Camp Oneqwah will provide you transportation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12764] = { id = 12764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Secret to Kungaloosh", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12765] = { id = 12765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kungaloosh", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12766] = { id = 12766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with your Ambassador", description = "<The dragon in elf form takes your letter of introduction, perusing it for a moment and then stashing it away within his sleeve.>\n\nEverything seems to be in order. However, if you don't mind, I would ask that you speak with your ambassador here at the temple.\n\nShe has something of great import for you that needs taking care of before we send you up to the queen.\n\n<He pats at the letter under his sleeve.>\n\nI'll keep this safe for you until your return.", completion = "You must be {name}. I was told you'd be coming.\n\nI have something that I think you're uniquely qualified to take care of and by doing it, you'll be ingratiating yourself with the dragons here.", objectives = "Speak with Lauriel Trueblade at Wyrmrest Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12767] = { id = 12767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with your Ambassador", description = "<The dragon in elf form takes your letter of introduction, perusing it for a moment and then stashing it away within his sleeve.>\n\nEverything seems to be in order. However, if you don't mind, I would ask that you speak with your ambassador here at the temple.\n\nHe has something of great import for you that needs taking care of before we send you up to the queen.\n\n<He pats at the letter under his sleeve.>\n\nI'll keep this safe for you until your return.", completion = "You must be {name}. I was told you'd be coming.\n\n\n\nI have something that I want you to take care of. If you do, you'll prove yourself to the dragons here.", objectives = "Speak with Golluck Rockfist at Wyrmrest Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12768] = { id = 12768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Steward of Wyrmrest Temple", description = "You've proved that you're to be trusted and more.\n\nYou should return to Wyrmrest Temple and speak with the steward, Tariolstrasz, once more, {name}.", completion = "Back so soon, {name}?\n\nCeristrasz sent word ahead of you. Thank you for what you did at the Ruby Dragonshrine.", objectives = "Speak with Tariolstrasz at Wyrmrest Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12769] = { id = 12769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Steward of Wyrmrest Temple", description = "You've proved that you're to be trusted and more.\n\nYou should return to Wyrmrest Temple and speak with the steward, Tariolstrasz, once more, {name}.", completion = "Back so soon, {name}?\n\nVargastrasz sent word ahead of you. Thank you for what you did at the Ruby Dragonshrine.", objectives = "Speak with Tariolstrasz at Wyrmrest Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12770] = { id = 12770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reallocating Resources", description = "Listen up, {class}!\n\nYour days here are numbered. As much as we need capable {class}s in our ranks, there's trouble up north that makes our problems look like a mid-summer Stormwind parade.\n\nTurns out the Scourge are concentrating their efforts - making a big push to take over Zul'Drak. If that happens, we may as well pack it in.\n\nYou're free to finish any business here, but then it's off to Light's Breach with you. Speak to Samuel if you need transportation.\n\nDismissed.", completion = "The Light shall prevail!", objectives = "Gryan Stoutmantle wants you to report to Sergeant Riannah at Light's Breach in Zul'Drak.\n\nYou may speak to Samuel Clearbook for transportation to Light's Breach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12771] = { id = 12771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ironforge", description = "Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King's machinations.\n\nTake this, {name}.  Guard it close, and secure its passage to Ironforge.  Magni Bronzebeard is eager to take the fight to Northrend, and this will bring him closer to his goal.", objectives = "Bishop Lazaril wants you to bring the Light-infused Artifact to King Magni Bronzebeard in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12772] = { id = 12772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Desperate Alliance", description = "Good {name}, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion.  Only by joining our strengths can the two great cultures of Azeroth survive against his assault.\n\nIn Shattrath, in the Terrace of Light, that alliance has been struck.  To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.\n\nLight speed, {name}.", sourceObjective = "Speak with Bishop Lazaril in the new Alliance camp at the Terrace of Light in Shattrath.Good {name}, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion. Only by joining our strengths can the two great cultures of Azeroth survive against his assault.\n\nIn Shattrath, in the Terrace of Light, that alliance has been struck. To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.\n\nLight speed, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12773] = { id = 12773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darnassus", description = "Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King's machinations.\n\nTake this, {name}.  Guard it close, and secure its passage to Darnassus.  Deliver it to Tyrande Whisperwind -- her priests will find it a vital source of power in their fight against the unholy forces from the North.", objectives = "Bishop Lazaril wants you to bring the Light-infused Artifact to Tyrande Whisperwind in Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12774] = { id = 12774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormwind", description = "Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King's machinations.\n\nTake this, {name}.  Guard it close, and secure its passage to Stormwind.  The King of Stormwind has recently returned; I'm sure he will welcome this tool.", objectives = "Bishop Lazaril wants you to bring the Light-infused Artifact to King Anduin Wrynn in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12775] = { id = 12775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Desperate Alliance", description = "Good {name}, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion.  Only by joining our strengths can the two great cultures of Azeroth survive against his assault.\n\nIn Shattrath, in the Terrace of Light, that alliance has been struck.  To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.\n\nLight speed, {name}.", sourceObjective = "Speak with Bishop Lazaril in the new Alliance camp at the Terrace of Light in Shattrath.Good {name}, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion. Only by joining our strengths can the two great cultures of Azeroth survive against his assault.\n\nIn Shattrath, in the Terrace of Light, that alliance has been struck. To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.\n\nLight speed, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12776] = { id = 12776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Exodar", description = "Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King's machinations.\n\nTake this, {name}.  Guard it close, and secure its passage to the Exodar.  Deliver it to Prophet Velen in the Vault of Lights so that he may use its powers against the unholy forces from the North.", objectives = "Bishop Lazaril wants you to deliver the Light-infused Artifact to Velen in the Exodar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12777] = { id = 12777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Desperate Alliance", description = "Good {name}, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion.  Only by joining our strengths can the two great cultures of Azeroth survive against his assault.\n\nIn Shattrath, in the Terrace of Light, that alliance has been struck.  To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.\n\nLight speed, {name}.", sourceObjective = "Speak with Bishop Lazaril in the new Alliance camp at the Terrace of Light in Shattrath.Good {name}, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion. Only by joining our strengths can the two great cultures of Azeroth survive against his assault.\n\nIn Shattrath, in the Terrace of Light, that alliance has been struck. To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.\n\nLight speed, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12778] = { id = 12778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scarlet Apocalypse", description = "The trap has been sprung, death knight. The armies of Hearthglen and Tirisfal have arrived, just in time to see their enclave in flames! If they turn back now, they fight us with their backs turned.\n\n<Mograine shakes his head.>\n\nNo, they have only one option, which has only one outcome: APOCALYPSE!\n\nAs we speak, they prepare to make one final stand.\n\nThe Lich King awaits your return, champion. He stands watch below us, at Death's Breach.", completion = "You have served me well, {name}. The mark of the Scourge has been burned into these Scarlet lands. You have reaped death and destruction for as far as the eye can see and delivered to me the last of the Scarlet armies.\n\n\n\nIt is now time to finish what you started.", objectives = "Seek out the Lich King at Death's Breach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12779] = { id = 12779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An End To All Things...", description = "You have slaughtered legions beyond number and still your dark heart craves more. Your hunger knows no end, {name}.\n\n<The Lich King pauses.>\n\nThere must come an end to all things, death knight. The Scarlet armies make their final stand against us. For them, there is no escape... no choice. And for this reason they will fight with a ferocity that you have yet to witness.\n\nUse this horn to call forth one of my wyrms. Climb upon its back and command it into battle. With it you will end the Scarlet Crusade.", progress = "Kill them all...", completion = "Kneel, champion. I place this helm upon your head to complete your terrifying visage. Any that dare look upon your dark countenance will know that death comes. Let none stand so boldly against your king so as to face your merciless wrath, {name}.\n\nThere remains only one final task...\n\n\n\nLight's Hope Chapel.", objectives = "The Lich King has commanded you to eradicate the Scarlet Crusade.\n\nUse the Horn of the Frostbrood to call forth a Frostbrood Vanquisher and with it slay 150 Scarlet Soldiers and destroy 10 Scarlet Ballistas. Avoid incoming projectiles by moving out of their line of fire!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12780] = { id = 12780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DEPRICATED>>Enemy of Our Enemy", description = "As much as we find working with death knights distasteful, we cannot afford to be picky about our allies here.\n\nWe're pinched between the Scourge and the savage Drakkari, who want nothing more than to destroy us so that they can get at one another.\n\nTravel west to Ebon Watch. Speak with Stefan and see if you can be of service to him.", sourceObjective = "Sergeant Riannah in Light's Breach wants you to speak with Stefan in Ebon Watch and offer your assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[12781] = { id = 12781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Siouxsie the Banshee in Ebon Hold.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!You will be able to choose one of these rewards:", objectives = "Bring the Ebon Hold Gift Voucher to Siouxsie the Banshee in Ebon Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12782] = { id = 12782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Research", description = "{name}, the Lich King plagues us with invasion.  To beat him back to his frozen throne, the Horde and Alliance must stand resolute together.  In Shattrath, in the Terrace of Light, that alliance has been struck.\n\nTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress.  He leads desperate research to end the zombie plague.  His cure is our salvation.\n\nBe swift, {name}.  Each moment passed is another innocent life lost.", sourceObjective = "Speak with Grand Apothecary Putress in the new apothecary camp at the Terrace of Light in Shattrath.{name}, the Lich King plagues us with invasion. To beat him back to his frozen throne, the Horde and Alliance must stand resolute together. In Shattrath, in the Terrace of Light, that alliance has been struck.\n\nTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress. He leads desperate research to end the zombie plague. His cure is our salvation.\n\nBe swift, {name}. Each moment passed is another innocent life lost.", sourceObjectiveStatus = "unverified-source-field" }
quests[12783] = { id = 12783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Research", description = "{name}, the Lich King plagues us with invasion.  To beat him back to his frozen throne, the Horde and Alliance must stand resolute together.  In Shattrath, in the Terrace of Light, that alliance has been struck.\n\nTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress.  He leads desperate research to end the zombie plague.  His cure is our salvation.\n\nBe swift, {name}.  Each moment passed is another innocent life lost.", sourceObjective = "Speak with Grand Apothecary Putress in the new apothecary camp at the Terrace of Light in Shattrath.{name}, the Lich King plagues us with invasion. To beat him back to his frozen throne, the Horde and Alliance must stand resolute together. In Shattrath, in the Terrace of Light, that alliance has been struck.\n\nTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress. He leads desperate research to end the zombie plague. His cure is our salvation.\n\nBe swift, {name}. Each moment passed is another innocent life lost.", sourceObjectiveStatus = "unverified-source-field" }
quests[12784] = { id = 12784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Research", description = "{name}, the Lich King plagues us with invasion.  To beat him back to his frozen throne, the Horde and Alliance must stand resolute together.  In Shattrath, in the Terrace of Light, that alliance has been struck.\n\nTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress.  He leads desperate research to end the zombie plague.  His cure is our salvation.\n\nBe swift, {name}.  Each moment passed is another innocent life lost.", sourceObjective = "Speak with Grand Apothecary Putress in the new apothecary camp at the Terrace of Light in Shattrath.{name}, the Lich King plagues us with invasion. To beat him back to his frozen throne, the Horde and Alliance must stand resolute together. In Shattrath, in the Terrace of Light, that alliance has been struck.\n\nTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress. He leads desperate research to end the zombie plague. His cure is our salvation.\n\nBe swift, {name}. Each moment passed is another innocent life lost.", sourceObjectiveStatus = "unverified-source-field" }
quests[12785] = { id = 12785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orgrimmar", description = "We have a breakthrough!  Our zombie specimens have given us new insight into the nature of the Scourge's plague.  They have born rotten, delicious fruit...\n\nTake this box to Orgrimmar.  Inside is a head that is infected with the zombie plague, and something else we have devised -- an anti-plague.  The two plagues battle within the zombie brain, and that brain is the key to a cure, I am certain of it.\n\nBring the box to my assistant, Apothecary Karlov.  He attends Warchief Thrall in Orgrimmar.", objectives = "Grand Apothecary Putress wants you to give the Dual-plagued Brain to Apothecary Karlov in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12786] = { id = 12786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunder Bluff", description = "We have a breakthrough!  Our zombie specimens have given new insight into the nature of the Scourge's plague.  They have born rotten, delicious fruit...\n\nTake this box to Thunder Bluff.  Inside is a head that is infected with the zombie plague, and something else we have devised -- an anti-plague.  The two plagues battle within the zombie brain, and that brain is the key to a cure, I am certain of it.\n\nBring the box to my assistant, Apothecary Chaney.  He attends Magatha Grimtotem in Thunder Bluff.", objectives = "Grand Apothecary Putress wants you to give the Dual-plagued Brain to Apothecary Chaney in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12787] = { id = 12787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Undercity", description = "The zombie plague was a blessing in disguise.  In our search for a cure, we have learned so much of the Scourge and their contagion.  Our research has given us weapons against them.  Weapons, and tools...\n\nTake this -- it is a zombie's head and has been partially cured of its plague by injecting it with a compound derived from our recent discoveries.  Deliver the head to Master Apothecary Faranell; I have a list of experiments I would like him to perform on it.", objectives = "Grand Apothecary Putress wants you to give the Dual-plagued Brain to Master Apothecary Faranell in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12788] = { id = 12788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silvermoon", description = "We have a breakthrough!  Our zombie specimens have given new insight into the nature of the Scourge's plague.  They have born rotten, delicious fruit...\n\nTake this box to Silvermoon City.  Inside is a head that is infected with the zombie plague, and something else... an anti-plague.  The two plagues battle within the zombie brain, and that brain is the key to a cure, I am certain of it.\n\nBring the box to my assistant, Apothecary Tepesh.  She attends Lor'themar Theron in Silvermoon City.", objectives = "Grand Apothecary Putress wants you to give the Dual-plagued Brain to Apothecary Tepesh in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12789] = { id = 12789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Breach!", description = "Ready yourself, {class}. I'm dispatching you to Light's Breach, northeast of here.\n\nI've received word that the Scourge are making a push to take over Zul'Drak.\n\n<Valus stares you dead in the eyes.>\n\nThis will not come to pass.\n\nSee to it that you assist in the destruction of the Scourge there. The light demands it.\n\nDismissed.", completion = "Excellent. Valus must have received my report.\n\nLet's get to work, {race}.", objectives = "Crusader Valus at Light's Trust wants you to report to Sergeant Riannah at Light's Breach in Zul'Drak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12790] = { id = 12790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning to Leave and Return: the Magical Way", description = "Just in case you don't already know, you can use the crystal on the platform behind me to teleport to the Violet Stand in Crystalsong Forest beneath Dalaran.\n\nCorrespondingly, you can use the crystal at the stand below to return to the chamber above me.\n\nI would like for you to do this now.", progress = "I sense that you haven't yet tested out both of the teleport crystals.\n\nThat's alright, take your time.", completion = "Excellent, {class}. Now you know the way to get down to Crystalsong Forest and also how to return.", objectives = "Archmage Celindra at The Violet Gate in Dalaran wants you to use the Teleport to Violet Stand Crystal and the Teleport to Dalaran Crystal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12791] = { id = 12791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Magical Kingdom of Dalaran", description = "Hello, {name}. You may or may not be aware that we Kirin Tor moved our city here to Northrend.\n\nNo longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest.\n\nWe believe you to be ready for your journey to the city. Speak with me again and I will cast a spell of teleportation to transport you there.\n\nWhen you arrive, seek out Archmage Celindra and give her my signet as proof that we spoke.", progress = "Greetings, {class}.", completion = "Welcome to Dalaran.\n\nI'll see to it that the ring is returned.", objectives = "Deliver the Kirin Tor Signet to Archmage Celindra at The Violet Gate in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12792] = { id = 12792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Things First", description = "Listen up, {race}!\n\nThis entire region is full of crises. Everywhere you look you'll find those who could use your assistance.\n\n<Kunz looks you squarely in the eye.>\n\nNo one needs your help right now more than Riannah. The scourge have forced their way between us, leaving her and those she commands isolated.\n\nLight's Breach, where her forces are holding out, lies just southwest of here.", completion = "My report must have made it through to Kunz.\n\nIt is good to know that he is well.", objectives = "Commander Kunz at Argent Stand wants you to report to Sergeant Riannah at Light's Breach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12793] = { id = 12793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smoke on the Horizon", description = "You hear that, {race}?\n\nThe clamor of battle far to the west reaches us here, even over the din of our own struggle.\n\nThe Scourge are threatening to break through the lines of those calling themselves the Argent Crusade. Preventing this is as urgent as anything in the region.\n\nTravel to Light's Breach and join in their struggle. Speak to Maaka and he will provide you safe passage.", completion = "The Light shall prevail!", objectives = "Khufu in Zim'Torga wants you to travel to Light's Breach and report to Sergeant Riannah there.\n\nMaaka will provide you with transportation there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12794] = { id = 12794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Magical Kingdom of Dalaran", description = "Hello, {name}. You may or may not be aware that we Kirin Tor moved our city here to Northrend.\n\nNo longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest.\n\nWe believe you to be ready for your journey to the city. Speak with me again and I will cast a spell of teleportation to transport you there.\n\nWhen you arrive, seek out Archmage Celindra and give her my signet as proof that we spoke.", progress = "Greetings, {class}.", completion = "Welcome to Dalaran.\n\nI'll see to it that the ring is returned.", objectives = "Deliver the Kirin Tor Signet to Archmage Celindra at the Violet Gate in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12795] = { id = 12795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking a Stand", description = "A few moments ago I spotted a signal flare over the treeline to the east.\n\nThat can only mean that things are not going smoothly for the Crusaders at Argent Stand.\n\nI cannot leave our post here, {race}, but you can. When time permits, make your way up to Commander Falstaav and see if there's anything you can do to lighten their burden.", completion = "As it happens there is something you can do to be of assistance, {class}.", objectives = "Bloodrose Datura at Ebon Watch wants you to speak with Commander Falstaav at The Argent Stand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12796] = { id = 12796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Magical Kingdom of Dalaran", description = "Hello, {name}. You may or may not be aware that we Kirin Tor moved our city here to Northrend.\n\nNo longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest.\n\nWe believe you to be ready for your journey to the city. Speak with me again and I will cast a spell of teleportation to transport you there.\n\nWhen you arrive, seek out Archmage Celindra and give her my signet as proof that we spoke.", progress = "Greetings, {class}.", completion = "Welcome to Dalaran.\n\nI'll see to it that the ring is returned.", objectives = "Deliver the Kirin Tor Signet to Archmage Celindra at The Violet Gate in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12797] = { id = 12797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back Through the Waygate", description = "You speak the truth, {race}.  I can sense the very essence of Sholazar Basin begin to fray by the blight of undeath even as we speak.\n\nI've bound my being into the rune, {race}.  Deliver it to she who sent you here -- for only her power can grant me passage to her lands.", progress = "You've returned, {name}.", completion = "You've done well.\n\nWoe unto our enemies.  Woe unto those who serve the Lich King and threaten the titans' creations -- for the Etymidian is here.", objectives = "Bring the Omega Rune to the Avatar of Freya at the Rainspeaker Rapids in Sholazar Basin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12798] = { id = 12798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swords Deck", description = "Now that you have gathered all of the Swords cards together into a deck, another card appears on top.  It depicts a fortune teller that seems to stare at you no matter how you hold the card.\n\nYou feel the card could be used to communicate with someone.", progress = "I see that you have managed to complete a deck of Swords.  Excellent.", completion = "The tarot cards are of great interest to the Darkmoon Faire, so do not hesitate to call upon us if you manage to collect more.  We are not without our own skilled tradesmen, so please allow us to offer something in return.", objectives = "Use the Swords Deck to summon a Darkmoon Fortune Teller and give the deck to them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12799] = { id = 12799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siphoning the Spirits", description = "You should be happy he's coming, they said. You'll enjoy his company, they said....\n\nWell it's not as if I had a choice in the matter. Finklestein is the Crusade's best alchemist. I suppose I should be honored that he's chosen my post to set up shop. But ever since he's arrived, I've been relegated to collecting various alchemical ingredients.\n\nSay, {race}, how about you give me a hand? Just south of here are some pools that are haunted by spirits of ancient trolls. Collect their ectoplasm for me.", progress = "Good day, {race}.\n\nHave you collected the ectoplasm Finklestein asked for?", completion = "Thank you, {class}.\n\nThis should save my men some precious time.", objectives = "Captain Arnath at Heb'Valok wants you to collect 5 Ancient Ectoplasms from the Lost Drakkari Spirits at the Pools of Zha'Jin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12800] = { id = 12800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lich King's Command", description = "The Scarlet Enclave is no more. What remains of the Crusade will be dealt with in Northrend.\n\nWe now turn all of our efforts to Light's Hope Chapel. No longer will this affront to your master be allowed to exist!\n\nI have issued my final command. Scourge Commander Thalanor awaits your arrival at the edge of Browman Mill. Go northwest, through the cave, into the Noxious Glade and take the path leading out of the glade to the mill.\n\nDo not fail me, {name}.", completion = "The Highlord and the other death knights are preparing to strike! We will squeeze the last remnants of life out of this place.", objectives = "Report to Scourge Commander Thalanor at Browman Mill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12801] = { id = 12801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Light of Dawn", description = "The Argent Dawn stands defiantly against us at Light's Hope Chapel. They dare oppose the Scourge and for that reason alone they must be destroyed!\n\nThe mighty armies of the Lich King stand at the ready as the final battle for the Plaguelands approaches. Today we ascend into the immortal realm of Scourge heroes!\n\nWhen you are ready for battle, report to Highlord Darion Mograine. It is the highlord who will issue the final march orders and command our armies at Light's Hope Chapel.", progress = "<Highlord Mograine nods.>", completion = "There will be no atonement for us, {name}. We are forever damned to walk the earth as monsters. While the Lich King may have loosed his grip upon us, the specters of our past will forever haunt our memories.\n\nWe must make amends in the only way we know how: Death...\n\nI ask you now to join me in Acherus as a Knight of the Ebon Blade. Together we will destroy the Lich King and end the Scourge.", objectives = "Defeat the forces of the Argent Dawn and uncover the Light of Dawn.\n\nReport to Highlord Darion Mograine should you survive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12802] = { id = 12802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Heart is in Your Hands", description = "<Drakuru's voice fills your mind.>\n\nHey, mon! Dis eye of da prophets be great! I been usin' it to watch ya and I see ya got da heart now! Not bad....\n\nNow ya just gotta bring it to my brazier at Drak'atal Passage, a short walk east of ya.\n\nYa must drink my elixir at da pedestal to summon me there. This time, ya need ta mix in some desperate mojo from the defenders there for it ta be workin'.", completion = "Impressive, mon! Fate be kind in bringin' us together.\n\nSoon I be avengin' me bruddas by cleansin' Drak'Tharon, and you be awarded Drak'Tharon's greatest treasure.", objectives = "Drakuru wants you to bring the Heart of the Ancients to him at Drak'atal Passage.\n\nYou will need to collect 5 Desperate Mojo to use the elixir there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12803] = { id = 12803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Force of Nature", description = "I'm not sure about what I saw while flying to the northeast, but to me it looked like a gigantic woman kicking some Scourge butt.\n\nI'd heard the professor talk about a certain \"lifewarden\"  appointed by the titans to look over Sholazar.  I might not be a titan historian, but it sounds like she fits the bill.\n\nI also know that if the Scourge cross the border between the Lost Lands and the rest of Sholazar, our expedition's as good as dead.  What do you say you go look for her and lend a hand?", completion = "You are not of this land.  But you also are not with the Scourge.\n\nWhat should I make of you?", objectives = "Travel to the Blight Line, between Rainspeaker Rapids and the Lost Lands in Sholazar Basin and seek the Avatar of Freya.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12804] = { id = 12804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Steak Fit for a Hunter", description = "Sometimes, there's nothing worse than a camp full of hunters. They're all so busy taking down prey animals that the only meat I get is tough and stringy. That's hardly the kind of thing you want to come home to after a long day on the hunt.\n\nLucky for us, though, there is a source of tender, succulent meat nearby. To the south of the river and the camp live longneck grazers. They're a perfect source of meat for our hungry hunters. Bring me back the best cuts of meat and we'll properly toast our comrades.", progress = "Did you get those steaks?", completion = "Now that's a meal! If anything good came of the shipwreck, it's got to be that we've been spared eating nothing but salt beef for the next month! Thank you again, {name}.", objectives = "Bring 5 Longneck Grazer Steaks to Korg the Cleaver at the Nesingwary Base Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12805] = { id = 12805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salvaging Life's Strength", description = "The Lifeblood Pillar was toppled over with great force, sending the very earth into an upheaval.\n\nThe elementals that wander the sundered shard carry with them the very life essence that gave the pillar its strength.  I cannot allow this energy to be wasted, for only four pillars remain.\n\nHead to the sundered shard, to the southeast, and seek the lifeblood elementals.\n\nUse this gem on their remains to recover their rampant energy.  We'll need the energy to heal the land when all this is over.", completion = "I thank you, {name}.  It is a shame that the pillar has fallen, but we must salvage what we can.", objectives = "The Avatar of Freya wants you to go to the Sundered Shard to the southeast and use the Lifeforce Gem on 8 destroyed Lifeblood Elementals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12806] = { id = 12806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Rise with all Due Haste!", description = "Some would say that our most critical mission lies not with the Lich King, but with the utter destruction of the Scarlet Onslaught. I would say that is foolish, but who am I to judge?\n\nDeath's Rise is far to the southwest, overlooking the sea along the cliff wall. There you will find Lord-Commander Arete personally overseeing the Onslaught's destruction himself.\n\n<The baron clears his throat.>\n\nDo see to it that you report to him with all due haste. He asked for you personally.", completion = "It's about damned time! No doubt that Baron Sliver took his sweet time in sending you to me.\n\nI should have that empty space above his shoulders removed!", objectives = "Report to Lord-Commander Arete at Death's Rise in Icecrown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12807] = { id = 12807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Story Thus Far...", description = "We have much to do, but first I believe a short refresher is in order.\n\nWe death knights have a colorful past with our Scarlet friends who idiotically rest comfortably in the harbor below us to the northwest.\n\nWhen you are ready for an earful, speak with me again and I shall provide enlightenment.", completion = "In their folly, the Argent Crusade has chosen to turn a blind eye upon the presence of the Scarlet Onslaught. We will not.\n\nWe do not care if they might assist in the battle against the Lich King. We do not believe them worthy of existence. We will be their end, once and for all!", objectives = "Listen to Lord-Commander Arete's tale at Death's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12808] = { id = 12808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Desperate Alliance", description = "Good {name}, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion.  Only by joining our strengths can the two great cultures of Azeroth survive against his assault.\n\nIn Shattrath, in the Terrace of Light, that alliance has been struck.  To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.\n\nLight speed, {name}.", sourceObjective = "Speak with Bishop Lazaril in the new Alliance camp at the Terrace of Light in Shattrath.Good {name}, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion. Only by joining our strengths can the two great cultures of Azeroth survive against his assault.\n\nIn Shattrath, in the Terrace of Light, that alliance has been struck. To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.\n\nLight speed, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12809] = { id = 12809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ironforge", description = "Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King's machinations.\n\nTake this, {name}.  Guard it close, and secure its passage to Ironforge.  High Tinker Mekkatorque in Tinkertown will be eager to make use of the artifact's power.", objectives = "Bishop Lazaril wants you to bring the Light-infused Artifact to High Tinker Mekkatorque in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12810] = { id = 12810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood in the Water", description = "The forces at Onslaught Harbor are heavily reinforced by gryphon riders. You need a mount that will enable you to put them down. But first, we need the components for the ritual that is going to make it all happen.\n\nA great deal of blood is necessary for the ritual to be undertaken.\n\n<The lord-commander points down and to the northwest.>\n\nThere is a readily available supply down there in the harbor... sharks. Do not return to me until you've filled this bladder with their blood.", completion = "Well done. Take a moment to let the saltwater dry from your skin before we continue.", objectives = "Lord-Commander Arete at Death's Rise wants you to fill the Gore Bladder with the blood of 10 Ravenous Jaws.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12811] = { id = 12811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Research", description = "{name}, the Lich King plagues us with invasion.  To beat him back to his frozen throne, the Horde and Alliance must stand resolute together.  In Shattrath, in the Terrace of Light, that alliance has been struck.\n\nTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress.  He leads desperate research to end the zombie plague.  His cure is our salvation.\n\nBe swift, {name}.  Each moment passed is another innocent life lost.", sourceObjective = "Speak with Grand Apothecary Putress in the new apothecary camp at the Terrace of Light in Shattrath.{name}, the Lich King plagues us with invasion. To beat him back to his frozen throne, the Horde and Alliance must stand resolute together. In Shattrath, in the Terrace of Light, that alliance has been struck.\n\nTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress. He leads desperate research to end the zombie plague. His cure is our salvation.\n\nBe swift, {name}. Each moment passed is another innocent life lost.", sourceObjectiveStatus = "unverified-source-field" }
quests[12812] = { id = 12812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orgrimmar", description = "We have a breakthrough!  Our zombie specimens have given new insight into the nature of the Scourge's plague.  They have born rotten, delicious fruit...\n\nTake this box to Orgrimmar.  Inside is a head that is infected with the zombie plague, and something else we have devised -- an anti-plague.  The two plagues battle within the zombie brain, and that brain is the key to a cure, I am certain of it.\n\nBring the box to my assistant, Apothecary Karlov.  He attends Thrall in Orgrimmar.", objectives = "Grand Apothecary Putress wants you to give the Dual-plagued Brain to Apothecary Karlov in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12813] = { id = 12813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From Their Corpses, Rise!", description = "How kind... how generous our lord-commander is. Where he is flowers and sunshine, I am filled only with hatred.\n\nIt is not enough to end their miserable lives... I want them humiliated... debased!\n\nWhat could be more unspeakable than to be turned into that which you hate? To dedicate your existence to eradicating a thing, and then in the end to become it?\n\nHow sad.\n\nTake this tincture northwest to Onslaught Harbor. Apply it to their still corpses and watch what happens, but avoid the cathedral.", completion = "<The draenei death knight fixes you with a cold stare, her eyes dead as the grave. A sly grin creeps across her features.>\n\nI'll have more of the tincture prepared tomorrow. Until then, be well.", objectives = "Setaal Darkmender at Death's Rise has given you the Darkmender's Tincture. Apply it to the corpses of 10 of any of the Scarlet Onslaught units found at Onslaught Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12814] = { id = 12814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You'll Need a Gryphon", description = "What could be more fitting than to take one of their own gryphons to use against them? Go to Onslaught Harbor and take the reins to one of their gryphons from the dead clutches of its rider.\n\nReturn with the gryphon, delivering it to Uzo Deathcaller. He will see to its proper transformation and provide you with further instructions.", progress = "What took so long? Are their gryphons slow? We'll have to do something about that!", completion = "Oh yeah this is gonna be good!\n\nStand back... I'm gonna call down the wrath of the blood ritual!", objectives = "Deliver an Onslaught Gryphon to Uzo Deathcaller at Death's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12815] = { id = 12815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Fly Zone", description = "Now that you got your bone gryphon, I wantcha to take it back down there everyday and make a no fly zone over Onslaught Harbor.\n\nI gotta admit, mon, I don't really care if you use the bone gryphon to kill them gryphon riders or not. But I'm guessin' that if you do, you'll find it much easier to get to 'em.\n\nBesides, it's got lots of neat tricks you can use.", progress = "What you back so soon for? I know I can still see those Onslaught boys still flyin' around down there!", completion = "That's the spirit! And you know, I need this done every day that we're here.\n\nI hope you'll come back again tomorrow. Your bone gryphon will be waitin'.", objectives = "Uzo Deathcaller at Death's Rise wants you to kill 10 Onslaught Gryphon Riders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12816] = { id = 12816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate the Scourge of Silvermoon", description = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend Silvermoon from these accursed invaders? \n\nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", objectives = "Collect three Dim Necrotic Stones from the Scourge outside Silvermoon and investigate the glowing runic circles near their encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12817] = { id = 12817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate the Scourge of Exodar", description = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend the Exodar from these accursed invaders? \n\nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", objectives = "Collect three Dim Necrotic Stones from the Scourge outside the Exodar and investigate the glowing runic circles near their encampment. Then return to Lieutenant Kregor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12818] = { id = 12818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clean Up", description = "To the point... Ricket's asked me to put together some stronger land mines, but I'm running low on parts.\n\nJust west of town, you'll find the remains of our last rocket sled... Ricket got a little excited when she was fueling it, but I probably should have thought to not put the nozzle right over the exhaust. Live and learn, eh?\n\nThere should be a good stock of spare parts scattered around the destroyed sled... why don't you go ahead and chase off those scavengers and nab me some of that wreckage?", progress = "We have to have something we can use to insulate our engines against this cold... think, Jeer, think!\n\nOh hey! Did you get some of that wreckage for me?", completion = "These will do nicely, thanks!\n\nDid you happen to see Dim out there? I sent him out a long while back and he never came back. I hope he's alright.\n\nSpeaking of which... I wonder where Janks is...", objectives = "Jeer Sparksocket at K3 would like 10 pieces of Charred Wreckage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12819] = { id = 12819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Around the Corner", description = "Blast it! Where are my tools? I had them here just a moment ago.\n\nOh! I probably forgot them when I was setting up that minefield in the west. That's mildly inconvenient. I'd be quite appreciative if you could go get them for me. You'll need to watch your step though... you should be able to use the same path that I did to get out.\n\nOh, and don't try to fly in... I had the presence of mind to set up turrets to shoot down anything that might fly, and they aren't very discerning in who they target.", progress = "If Janks were here, I could have just sent him on this errand. Oh... on second thought... I'm not sure I told him where the safe path is anyway.\n\nGood thing I have you resourceful adventure types around, eh?", completion = "Ha ha! These are them! Thank you kindly. I hope you didn't have too much trouble traversing the field.", objectives = "Jeer Sparksocket at K3 would like Sparksocket's Tools retrieved from his minefield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12820] = { id = 12820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Delicate Touch", description = "I've been waiting an eternity for these mines! Well, a few days at least. What took him so long?\n\nHere's the low down, compadre... there's this nasty bunch of magnataur--you know, big, hairy, and extremely ugly--and they seem pretty keen on taking K3 for themselves.\n\nNot going to happen.\n\nWe've got some defenses set up in their path, northeast of here. Sadly, our laser turrets have pretty limited power supplies... that's where these mines come in! Get over there and blow them up good!", completion = "So... here I sat, basking in the awesomeness that is me, and in the distance, I hear a pop! Then another! Then a dozen more! And a smile crept onto my face at the thought of all those magnataur and snobolds eagerly rushing to their own deaths.\n\nWas it glorious?", objectives = "Ricket at K3 wants you to use Improved Land Mines at Garm's Bane to fend off 12 attackers from Garm. Both Garm Invaders and Snowblind Followers will count towards this goal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12821] = { id = 12821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cell Block Tango", description = "The sapper squad is ready. That means it's time for fun!\n\nThere's only one thing holding us up from our full-scale assault on Garm! I sent a runner to set a teleporter up behind him--successfully I might add--and he returned to get the power cell it needs to function. It isn't working yet... which means the power cell didn't get there.\n\nI need you to look just on the other side of Garm's Bane for the power cell. When you find it, bring it farther east to Garm's Rise and activate the teleporter.", progress = "Even magnataur should know not to mess with goblins.", completion = "Excellent!\n\n<A fierce grin creeps onto Ricket's face.>\n\nLet the destruction begin!", objectives = "Ricket at K3 would like you to locate the Transporter Power Cell and use it to activate the Transportation Pad at Garm's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12822] = { id = 12822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Know No Fear", description = "Now that we have the teleporter open, my plan is quite complex... it has several facets and will take impeccable coordination. And there are supplies to be gathered! And troops to recruit! Likely, weeks of hard labor as well!\n\nHahah, I had you going there for a moment, didn't I? You've got this, kid. Hop through the teleporter and take the fight to them! Our sappers will back you up... they won't have anywhere to run.", completion = "Haha! That'll teach those brutes to waste our time. From this day forth, green skin will strike fear into the hearts of all magnataur!", objectives = "Ricket at K3 wants you to kill 6 Garm Watchers and 8 Snowblind Devotees.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12823] = { id = 12823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Flawless Plan", description = "Hey there! Joining us for the assault I assume?\n\nI've got a special task for you... we're going to bring the whole cave down on their heads! Towards the back of their cave, you should find Frostgut's Altar.  Sneak up and plant this hardpacked explosive bundle somewhere close to it.\n\nOnce the charge is placed, stick around just long enough to make sure Frostgut bites it, then get out quickly! There's no knowing how long the cave will last once that thing goes off!", progress = "That explosive bundle is my baby... it took me weeks to perfect it. WEEKS!\n\nThat's a long time... okay.", completion = "The whole mountain shook! Was it gorgeous? I bet it was! How could it not be?\n\nAnd the Inventor's League tells me all of my inventions just blow up. Darn right they do! Hah!", objectives = "Gino at Garm's Rise wants you to plant the Hardpacked Explosive Bundle near Frostgut's Altar, kill Tormar Frostgut, and then escape the cave before it collapses on you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12824] = { id = 12824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demolitionist Extraordinaire", description = "You've got some swift feet on you sonny! Thanks for lending a hand with those explosives... I've been waiting to give that invention a good test run for a while!\n\nGo ahead and tell Ricket we should be covered on the magnataur front now... my sappers will clean up any of the remaining baddies.\n\nThanks again!", completion = "You blew the whole place up? Way to go! I bet Gino got a kick out of that.\n\nWe really appreciate all of the help you've lent us, {name}. How 'bout a souvenir for your troubles?", objectives = "Return to Ricket at K3.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12825] = { id = 12825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expressions of Gratitude", objectives = "[PLACEHOLDER] Use mini-plane to kamakazi on the gnoll leader.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12826] = { id = 12826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slightly Unstable", description = "Looking good!\n\nNo, not you - my new mines. You're just a little full of yourself, aren't you? I, on the other hand, am absolutely brilliant! My intellect cannot be matched.\n\nWhat were we talking about? Oh yes, my new mines! New and improved... ready for whatever devious use Ricket has concocted.\n\nBe a <good lad/doll> and go hand them off to Ricket, will you? She's right over there... it should be quite the epic journey, I'm sure. Be careful though, she's a little loopy.", progress = "Jeer finished the mines? Dandy.", completion = "Well, aren't these just the cutest little packets of destruction you've ever seen?!", objectives = "Deliver Jeer's Improved Land Mines to Ricket in K3.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12827] = { id = 12827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaimed Rations", description = "Hey hey! You're a new face! Care to lend Ricket a hand?\n\nWe have a somewhat unexpected problem - food shortage. I know, I know... we should have seen that coming, but you don't get it. We tend to have somewhat of a quick turn-around here with our sapper squad and all, so usually we don't have to worry about long term eats. Good old K3's gotten popular though.\n\nConvenient solution? There are gnoll camps to the west and some gnolls scattered, scavenging as gnolls do. Care to go nab some of their rations?", progress = "Hey there again! My belly's rumbling... how'd it go?", completion = "I hope they weren't too hesitant to share the wealth. We've been pretty forgiving with them picking through our leftovers thus far.", objectives = "Ricket at K3 wants you to repossess 16 Dried Gnoll Rations from the nearby Savage Hill Gnolls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12828] = { id = 12828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ample Inspiration", description = "Wow! That stuff is nasty. Not to account for gnoll taste or anything, but I figured whatever they had would at least be... edible?\n\nLet's get more creative.\n\nTore's got an explosive dispenser north of town... not far from the big cavern entrance, can't miss it. I'm sure she intends them for mining purposes of some sort, but I've got a better idea.\n\nGrab one of those things and rush it to one of the nearby mammoths... most of them are to the west. Collect the meat, bring it back.", progress = "I know my plan was brilliant. Don't even worry about it.\n\nDoes it feel good to be in the presence of greatness? A little tingly maybe?", completion = "And it's already well-done! I outdo myself sometimes.\n\nThanks much, friend!", objectives = "Ricket at K3 wants you to retrieve a U.D.E.D, use it to blow up a mammoth, and retrieve 8 Hearty Mammoth Meat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12829] = { id = 12829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moving In", description = "Hiya! The name's Tore. I  head up the mining operation here at K3... or I will shortly anyway!\n\nThis here cave is full of creepy-crawlies. I think we could do with a few less spiders before we move in - what'd you think?", completion = "Ha ha! Good to see you're up for some dirty work.\n\nMuch appreciated there, pal!", objectives = "Tore Rumblewrench outside of Crystalweb Cavern wants you to kill 12 Crystalweb Spiders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12830] = { id = 12830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ore Repossession", description = "We're moving in!\n\nThere were some snobolds here when we arrived... their mining operation seems to have met some unfortunate happenings though. Doesn't much matter - we were taking over soon anyway.\n\nI sent some of our miners in there to get me some ore samples that I can use to calibrate our machines for processing, but they haven't come back.\n\nMind going in there and nabbing some samples for me in their stead? The snobolds probably have some on them, though I'd expect most of them are dead by now.", progress = "Ya have some ore for me?", completion = "Woo! That's a ripe stench right there! You had to get hands-on with some of those snobolds, didn't ya?\n\nI do appreciate it though!", objectives = "Tore Rumblewrench outside of Crystalweb Cavern would like you to retrieve 5 samples of Impure Saronite Ore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12831] = { id = 12831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Only Partly Forgotten", description = "Oi... it's like there's a propeller in my stomach.\n\nI think I can walk, but I got something nasty in my system when I got bit by something in the back of the cave. It was bigger than the other spiders... and brightly colored.\n\nRicket can probably make me an antidote, but she'd need the venom sac from whatever bit me. Would you mind finding it for me? I don't think Tore's coming.\n\nI'll just pretend I'm dead here and hopefully they'll leave me alone.", progress = "<The Injured Goblin Miner writhes in pain.>", completion = "That should cut it... I hope Ricket can put something together for me. Ready to get out of there, then?", objectives = "An Injured Goblin Miner in Crystalweb Cavern wants you to bring back an Icetip Venom Sac from an Icetip Crawler.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12832] = { id = 12832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bitter Departure", description = "Oi - thank you! I thought for sure I'd just be a spider snack. Perhaps I'm speaking a bit soon though - let's get the heck out of here!\n\nLet me know as soon as you're ready to go... make it quick.", completion = "Thanks for helping out our miner back there, {name}! I should be able to put together an antidote no problem.\n\nIf you stumble into Tore again, tell her that she's a jerk for me, will ya?", objectives = "Escort the Injured Goblin Miner out of Crystalweb Cavern and then speak to Ricket at K3.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12833] = { id = 12833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overstock", description = "Hey there again! You didn't run off like all the other adventurers did? Well, you're just a peach, aren't ya? I was beginning to think I smelled funny or something!\n\nWe could still use a bit of a hand around here, and you have just the right experience.  Remember those magnataur? Well apparently the cave didn't completely collapse... there are still quite a few left. So much for Gino taking care of them, eh?\n\nFortunately, Jeer made way more than enough mines. You've got this!", completion = "I like you. In fact, you rock!\n\nYay for you!", objectives = "Ricket at K3 wants you to use Improved Land Mines at Garm's Bane to fend off the attackers from Garm. Both Garm Invaders and Snowblind Followers will count towards this goal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12834] = { id = 12834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Rain, Nor Snow, Nor Exploding Plane", objectives = "[PLACEHOLDER] Test cold-weather bomber on giant.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12835] = { id = 12835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Grown Up", objectives = "[PLACEHOLDER] Test Grown Up Jormungar on Giant", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12836] = { id = 12836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expression of Gratitude", description = "I know just the job for an eager newcomer! We've got a gnoll problem. You might even call it a gnoll infestation! Pesky things. They keep creeping up more and more, and now they're on our doorstep, stealing our parts! Inconceivable.\n\nIt all begins and ends with their uppity leader, Gnarlhide. I want you to see to that \"ends\" part. Go pay him a visit at his camp all the way to the west, in Snowblind Hills.\n\nAnd when I say \"pay him a visit,\" that's a euphemism for \"kill him painfully.\" Kay? Kay!", completion = "Groovy! You're my kind of {race}.", objectives = "Ricket at K3 wants you to kill Gnarlhide.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12837] = { id = 12837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tore's Got the Goods", objectives = "[PLACEHOLDER] Report to Tore", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12838] = { id = 12838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intelligence Gathering", description = "I need to know what the Scarlet Onslaught is planning today. You will be my instrument in this task.\n\nFly to Onslaught Harbor and rifle through their baggage trunks for documents. The trunks will be locked, so you'll have to take the keys from the Scarlet Onslaught members by whatever means.", progress = "You have information for me?", completion = "Hand them over. I will sift through the useless ones and if there's anything actionable, I will call upon you.\n\nEither way, return tomorrow. It is well known that they change their plans on a daily basis.", objectives = "Aurochs Grimbane at Death's Rise wants you to collect 5 Onslaught Intel Documents.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12839] = { id = 12839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand (Admiral's) Plan", description = "At first this note looks like any of the other intel that you've been looking for. However, a quick perusal of its contents disabuses you of this notion.\n\nThe letter conveys that Grand Admiral Westwind is present somewhere on the island, but that he is keeping himself secluded for now. He speaks of a glorious day that is coming soon in which the Scarlet Onslaught will wash over first the Lich King and then the rest of world to finally bring order to Azeroth.\n\nThe lord-commander will want to see this!", progress = "Scarlet Onslaught intel is to be delivered to Aurochs Grimbane.\n\n<The lord-commander gives you an expectant look by way of a dismissal.>", completion = "A note written by Westwind? Why didn't you say so?\n\n<Arete tears the letter from your hand to read it.>\n\nThe fool! He's actually here?!\n\n<The lord-commander laughs.>\n\nThis is new information. I wonder how he imagines that he's going to conquer the world once he's taken down the Lich King? Not that he could accomplish either task in his wildest imaginings.", objectives = "Deliver the Note from the Grand Admiral to Lord-Commander Arete at Death's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12840] = { id = 12840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Strict Confidence", description = "If anyone knows where the admiral is, then surely it must be his captains on the ships in Onslaught Harbor.\n\n<The lord-commander rubs his hands together.>\n\nWelsington and Hartford are their names if memory serves. Go beat the information out of them and then end their miserable lives.\n\nI want to know where the grand admiral is hidden!", completion = "They resurrected Landgren? He's the one that will know where the grand admiral is then!", objectives = "Lord-Commander Arete at Death's Rise wants you to beat information out of Captains Welsington and Hartford.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12841] = { id = 12841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crone's Bargain", description = "Yes, it must be the little green prisoner you're after...  We might be able to help each other.\n\nYou're not going to get the goblin out of here by force. Not alive, anyway.\n\nAmong my people I am known as a Yrkvinn, a practitioner of illusions. As you can see, the Hyldnir have made me their prisoner.\n\nIf I had my runes, I could make you go unnoticed among them. Further inside, patrolling the mines, you'll find an overseer named Syra. She has my runes. Retrieve them and we'll talk some more.", progress = "My runes, {name}?  Do you have them?", completion = "I wasn't sure you were coming back.  I dread to think what will happen to me if I stay here for much longer.", objectives = "Lok'lira the Crone inside the Forlorn Mine wants you to retrieve the Runes of the Yrkvinn from Overseer Syra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12842] = { id = 12842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runeforging: Preparation For Battle", description = "The mark of war is etched indelibly upon your soul, death knight. You have learned the dark art of runeforging and with it you will engrave runes of power upon your weaponry.\n\nPreparations for battle must be made. Return to one of the runeforges, here in the Heart of Acherus, and use the power of runeforging to emblazon your weapon with a rune of power!\n\nReturn to me when your blade glows with dark energy!", progress = "Do not waste time, {name}. We are on the brink of apocalypse!", completion = "Remember these words, {class}: The Runeforge is a Scourge instrument. It exists only in Acherus, Naxxramas and the heart of Icecrown! You may only emblazon your weaponry at a Runeforge.\n\nReturn often and emblazon all of your weapons. A {class} must be prepared for all that would dare oppose him!", objectives = "Instructor Razuvious in Ebon Hold has commanded you to use your Runeforging ability in your spellbook to engrave a rune upon your Runed Soulblade.\n\nYou may freely replace the engraving upon your weapon at any time, so long as you are near a Runeforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12843] = { id = 12843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Took Our Men!", description = "You have to help us!  We were in the middle of an expedition into the mountains to set up a transmission tower when we were attacked.\n\nThey looked like vrykul, except their skin was blue and layered with frost... and they were all female!  They took all the men in the expedition and let us women go.  Please, {name}!  We think they're being held in Sifreldar, the village overlooking K3.", completion = "You did it!  Our boys are back!", objectives = "Gretchen Fizzlespark wants you to go to Sifreldar Village and rescue 5 Goblin Prisoners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12844] = { id = 12844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Equipment Recovery", description = "Please, {name}.  When the Hyldnir took our men, they also took all our equipment.  Of course, it's more important that we get our boys back, but if you run into any of our equipment, I'd really appreciate it if you brought it back to us.\n\nYou'll find their village just above us, to the north.", progress = "Any luck with our equipment, {name}?", completion = "Thanks, {name}!  We'll see what we can do to salvage these parts!", objectives = "Gretchen Fizzlespark wants you to obtain 8 pieces of K3 Equipment in Sifreldar Village north of K3.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12845] = { id = 12845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dalaran Teleport Crystal Flag" }
quests[12846] = { id = 12846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave No Goblin Behind", description = "All of our boys are back... thanks to you, {name}!  Well... all but one.\n\nMy brother Zeev is still up there according to the others.  Apparently they have some sort of mine where they make their prisoners work.  Go in there and see if you can find out anything.", completion = "You're definitely not with the Hyldnir... so what are you here for?  Ah... you must be looking for the new prisoner!", objectives = "Find the entrance to the Forlorn Mine in northern Sifreldar Village and look for clues for Zeev Fizzlespark's whereabouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12847] = { id = 12847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Second Chances", description = "I'd heard they have an archbishop in their cathedral, but I had no idea that they'd resurrected and promoted Landgren! The Crimson Cathedral is heavily guarded with only one entrance, so you'll need help.\n\nWe still need to know where the grand admiral is, but this time we're not taking any chances!\n\nTake this device. It can be used to summon a gate for me to step through once you've killed the archbishop.\n\nI'll have my answers directly from his compelled soul! We will find Grand Admiral Westwind!", completion = "Hidden caves on the backside of the island. How very interesting.\n\nWell, at least now I know where all of my missing spies are.", objectives = "Kill Archbishop Landgren and then summon Arete's Gate in the presence of his corpse. Speak with Lord-Commander Arete inside The Crimson Cathedral once he's completed his questioning of the archbishop's spirit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12848] = { id = 12848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Endless Hunger", description = "The endless hunger will soon take hold of you, {class}. When it does, you will feel pain immeasurable. There is only one remedy for the suffering: the hunger must be sated.\n\nI give you the key to your salvation.\n\nChained to the Heart of Acherus are those deemed unworthy of the dark brotherhood. Use the key to free an unworthy initiate. Allow them to equip their gear and battle you for their freedom. Kill and the pain will cease. Fail and suffer for eternity.\n\nLive or die - the choice is yours to make.", progress = "Two lives, one key... Do not fail me, {name}.", completion = "As expected, my chosen knight has triumphed! You are ready, {name}.", objectives = "Instructor Razuvious in Ebon Hold has commanded you to free an Unworthy Initiate and then kill the Unworthy Initiate in cold blood!\n\nIt's your life or theirs!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12849] = { id = 12849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power Of Blood, Frost And Unholy", objectives = "Within the Hall of Command you will find the schools of blood, frost and unholy. Each school has a trainer that can provide you with knowledge in the various dark arts.\n\nI, Lord Thorval, am the headmaster of the school of blood. Lady Alistra reigns over unholy and the arch-lich, Amal'thazad, holds dominion over frost.\n\nYou must return here whenever you gain power and train!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12850] = { id = 12850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report To Scourge Commander Thalanor", description = "Scourge Commander Thalanor awaits your arrival at the overhang located directly southeast of our current position. Report to Thalanor and requisition a Scourge gryphon to deliver you to Death's Breach.\n\nPrince Valanar will be waiting for you down below.\n\nSuffer well, <brother/sister>!", completion = "The war has begun, {class}! I shall place you upon my finest gryphon and deliver you to Death's Breach. Chaos, death, destruction! You will herald in all of this and more!", objectives = "Report to Scourge Commander Thalanor at the balcony on the first floor of Ebon Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12851] = { id = 12851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bearly Hanging On", description = "The test awaits, woman!\n\nDo you have the heart of a warrior queen? Or that of a sniveling seamstress?\n\nOne taste of war and you'll know the answer.\n\nYou might lie to your mother, your sisters, and even yourself, but the battlefield always exposes one's true nature.\n\nWhen you've made your preparations, mount Icefang and ride into battle. From her back, you must rain down a shower of death upon our enemy.", progress = "Have you survived the battle, {name}?", completion = "Perhaps you do have the heart of a warrior.\n\nTime will tell...", objectives = "Brijana at Brunnhildar Village wants you to mount Icefang and shoot 7 Frostworgs and 15 Frost Giants in the Valley of Ancient Winters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12852] = { id = 12852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Admiral Revealed", description = "When High General Abbendis was confronted at New Hearthglen, the grand admiral protected himself within an impenetrable sphere of magic before making his escape.\n\nI am particularly adept at nullifying magic.\n\nTake this to use against him inside The Hidden Hollow when he puts the sphere up. I wish that I could be there to see the look on his face when you do it.\n\nDeal with him.", completion = "MAL'GANIS?!!\n\n<The lord-commander laughs with abandon.>\n\nThe fools were taken in by the demons yet again and now they are destroyed!\n\nI trust that my favorite {class} will stick around long enough to help us finish off the rest of them? Perhaps one of these would convince you?", objectives = "Lord-Commander Arete wants you to deal with Grand Admiral Westwind. Return to the lord-commander upon Death's Rise after you have done so.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12853] = { id = 12853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luxurious Getaway!", description = "Hey there, pal!\n\nDo you like excitement and explosions?! Who doesn't? I know just the place for you. Down at luxurious K3, they're always making innovative inventions and finding all-new ways to make things blow up! Sounds thrilling, doesn't it? If you want to be part of the fun, head on down today and speak to Jeer Sparksocket!\n\nMandatory disclaimer: manual labor may be required to partake in previously indicated \"excitement.\"", completion = "Welcome to K3!\n\nWe came here to make our way into those peaks and get our fair share of some of those amazing titan machines. Progress on that end has been somewhat minimal, though. Gnolls, snobolds, magnataur... there's no shortage of trouble to go around... not to mention, we can't seem to keep any fliers in the air without their motors freezing.\n\nThere's plenty of work to be done though - lend a hand, eh?", objectives = "Speak to Jeer Sparksocket at K3 in the Storm Peaks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12854] = { id = 12854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Brann's Trail", description = "After the discovery of Brann's journal in Grizzly Hills, we've only had one other communication from Brann. A mysterious note found its way to Explorers' League headquarters in Ironforge, with no indication of where it came from. All it said was that we're to meet Brann at his camp and help him with his search.\n\nFrom what I can tell, the camp should be located northeast of here, across the Bor's Breath River and at the foot of some ruins from the Path of the Titans.", progress = "Did you find Brann's camp?", completion = "<Archaeologist Andorin looks at you expectantly.>\n\nYou were supposed to come back with Brann, not a piece of paper. What's going on here?", objectives = "Retrieve the Burlap-Wrapped Note from Brann's camp and return it to Archaeologist Andorin at Frosthold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12855] = { id = 12855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sniffing Out the Perpetrator", description = "The tone of Brann's note suggests he meant to bury something with the note, maybe a pack of some kind. You're sure this was all you found?\n\nOkay, I'm going to have you take one of these frosthounds with you. The frostborn use them for tracking. Bring it to the destroyed camp and let it get Brann's scent.\n\nIt should at least lead you to the location of those missing possessions, and if we're lucky, Brann himself.", completion = "You... you're not a member of the Explorers' League, at least not one I remember. But, if you recovered the communicator, they must've sent you. Good, that's almost what I was hoping for.", objectives = "Use the Frosthound Collar at the Abandoned Camp to track down whoever took Brann's possessions. When you recover them, use the communication device and speak to whoever you can contact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12856] = { id = 12856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cold Hearted", description = "To be slain honorably on the field of battle brings us all glory. To be frozen in a block of ice and endlessly taunted does not....\n\nYou are to fly to the frost giant city of Dun Niffelem, just east of the Valley of Ancient Winters, and liberate our captive proto-drakes. With them, you will be able to free our sisters from their frozen bonds and carry them safely home.\n\nBeware the giants' clubs, sister, lest you find yourself numbered among the captives.", progress = "Was your mission successful, sister?", completion = "Your efforts appear to have been successful, sister.\n\nYou have brought glory to the Brunnhildar!", objectives = "Free 3 Captured Proto-Drakes and rescue 9 Brunnhildar Prisoners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12857] = { id = 12857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Ragemane's Flipper", description = "Posted by Chief Rageclaw:\n\nChief Rageclaw trusty lion seal, Ragemane, bite hand that feed him. Rageclaw say Ragemane no more good because of bad Drakuru trolls. Chief Rageclaw very sad to ask that Ragemane be killeded and Ragemane flipper be returned to chief as proof.\n\nYou find Ragemane to southeast, at Rageclaw Lake.\n\nChief Rageclaw sorry for bad writing. First time use one of these things; plus, Chief Rageclaw is wolvar, not person.", progress = "Poor Ragemane. He was gift from brother-in-law.", completion = "<Chief Rageclaw cries.>\n\nHad Ragemane since pup. Sad day for Rageclaw. First troll attack Rageclaw, then troll make Ragemane bad. Rageclaw never trade with troll again!", objectives = "Recover Ragemane's Flipper and return it to Chief Rageclaw at Light's Breach in Zul'Drak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12858] = { id = 12858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pieces to the Puzzle", description = "Thank the Light that someone got my message. Now that I'm safe from the iron dwarves, I need to ask your help with something. I've got a lead on Norgannon's keystone, which guards access to Ulduar's archives, but the Titans divided it into two pieces and secreted them away.\n\nOne of the pieces, the keystone's shell, is held within the Inventor's Library on the northern coast, south of Ulduar itself. The first thing you'll need to do is retrieve the fragments of an access disk from the library's guardians.", progress = "Did you complete the disk?", completion = "Wonderful! Now that we have the disk, you must use it to open the Inventor's vault!", objectives = "Gather 6 Inventor's Disk Fragments and use them to assemble the Inventor's Disk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12859] = { id = 12859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Just In: Fire Still Hot!", description = "Trolls attack Rageclaw Den and kick Rageclaw out! It get worse. Trolls now burning village! This very bad. Chief make top Rageclaw shaman, Moky, do study on fire. Results very surprising! Fire still hot and can burn things.\n\nWill you help Rageclaw and put fire out? Moky has special Rageclaw fire extinguisher for you. Use special fire extinguisher to put out fire at Rageclaw Den to southeast. Sometimes take many sprays to douse fire, but extinguisher always have water! Rageclaw magic strong!", completion = "It strange because I know you put fire out, but fire still burning. Maybe this thing not so good after all, eh? Still, Moky pay you for what you do! Hopefully troll burn too!", objectives = "Elder Shaman Moky at Light's Breach in Zul'Drak wants you to use the Rageclaw Fire Extinguisher to douse 15 hut fires at Rageclaw Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12860] = { id = 12860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Data Mining", description = "That disk you assembled... it's blank! That crafty Mimir must've hidden the information somewhere else. Look around the Inventor's Library; do you see any databanks there?\n\nThat might be what you need to do with the disk. Try using it near some of those databanks. Perhaps it's set to retrieve and store information from them. After you've tried your hand at that, contact me again and let me know what you've found. Meanwhile, I'll be trying to track down the other half of the archive key.", progress = "Did you try using the disk? What did you find?", completion = "<Brann looks at the disk as you hold it up.>\n\nI can't tell if there's anything stored there or not! You have to tell me what happened.\n\n<You describe the data retrieval process.>\n\nSo it worked? At least we can count on Mimir to be systematic. Can't say that for the rest of these Keepers from what I've been hearing...", objectives = "Use the Inventor's Disk to retrieve 7 pieces of Hidden Data from the Databanks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12861] = { id = 12861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trolls Is Gone Crazy!", description = "Drakuru... You know who this troll is? I think bad troll are controlled by the Drakuru troll. They call themself Drakuru trolls - that how I know. Now you see why I am chief of Rageclaw. Smartest of all wolvar!\n\nBut that not why I talk to you now. Bad troll come and kick Rageclaw out of den. Rageclaw that no run away held as prisoner in village. You go to Rageclaw Den, southeast, and free captured Rageclaw. Kill troll for lock opener. You maybe kill many troll for many lock opener.", completion = "Rageclaw thank you, {name}. Though Rageclaw Den probably lost forever and troll-Rageclaw friendship also lost forever... and also now I think of it, Ragemane lost forever too. Also brother-in-law. He gone. Hrm, have you seen Chief's mate? I think she gone too.\n\nMaybe you go now. Chief a little depressed.", objectives = "Chief Rageclaw at Light's Breach in Zul'Drak wants you to use the Drakuru \"Lock Openers\" found on various Drakuru trolls to free 8 Captured Rageclaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12862] = { id = 12862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When All Else Fails", description = "So...  so I don't think we're going to be getting a good foothold in those mountains.\n\nTrust me, I'm not one to give up easily... but between freezing engines, nasty vrykul women, territorial dragon want-to-bes and the half a dozen other nasties settled in the area, this just ain't happening.\n\nDon't let that dissuade you though! Just because we can't get a foothold doesn't mean we won't get you there... one-way trips are pretty simple when you get down to it.\n\n<Ricket nods at some nearby rockets.>", completion = "Ow! That looked painful. It was a pretty grand entrance though, lad!\n\nWelcome to Frosthold! Are ya here to help us find a path into Icecrown?", objectives = "Speak to Ricket to make use of Ricket's D16 Propelled Delivery Device to enter further into Storm Peaks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12863] = { id = 12863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offering Thanks", description = "Ah! Thanks for coming up here, <lad/lass>.\n\nJudging by your wide eyes and shivering hands, I'd venture a guess that you're somewhat new. Sounds like it would be good for you to meet our gracious hosts then!\n\nWe've got some extra medical supplies... to be honest, we weren't expecting to have such a comfortable setup. Go ahead and give this crate to Glorthal over there, and lend them a hand if you would too. We don't want them to think we're ungrateful for how welcoming they've been.", progress = "Hello.", completion = "Medical supplies? Thank you! Not exactly sure what to do with them to be honest, but I'm sure they'll be useful.\n\nIt's good to meet you... there's such a colorful variety among your peoples. We're not used to having visitors up this way very often - it's good to have some fresh company.", objectives = "Bring the crate of medical supplies to Glorthal Stiffbeard in Frosthold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12864] = { id = 12864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Scouts", description = "There is something that I could use a hand with now that I have you.\n\nWe have a few scouts that are extremely late in returning. The peaks are harsh... but these boys know what they're doing.\n\nHead to the east... along the Bor's Breath valley and near Bor's Fall... they should be out that direction. If you find any sign of one of them, bring me back news immediately. We have a few enemies in the area - if any of them are getting a bit uppity, the more warning the better.", completion = "When a scout doesn't come back for this long... that's about the expected result. The harpies then?\n\nKing Stormheart has us train hard year round... he's turned us into amazing fighters. At times like this, I understand why it's necessary. He's the wisest and strongest leader I've yet seen among our people... don't let his peachy skin fool ya.", objectives = "Glorthal in Frosthold has requested a search of the Bor's Breath valley and Bor's Fall for any sign of the missing Frostborn Scouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12865] = { id = 12865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loyal Companions", description = "Fresh blood! Good to meet ya! I've got some work if you've got some time.\n\nOff to the east are the Foot Steppes... pretty hard land, but there's quite a group of rhino that graze there. Our birds have a taste for that rhino meat, but it's always a bit dangerous for them to go hunting with all of the proto-drakes that nest around there.\n\nIf you're keen, head over that way and get some rhino meat, bring it back to the peaks above here, and then use it to feed some of the eagles that nest there.", progress = "These birds have been loyal to us for a long time... we get on pretty well.", completion = "Thank you, kindly... and I'm sure they're quite appreciative too. They make powerful allies; you'll be well off being on this side of their graces.", objectives = "Fjorlin Frostbrow at Frosthold wants you to obtain 8 slabs of Fresh Ice Rhino Meat and use them to feed the Stormcrest Eagles above town.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12866] = { id = 12866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stemming the Aggressors", description = "Damn harpies. We've beat that bunch into submission more times than I can remember... and they stay quiet for a time after each bout. This time, I'd thought that maybe it sunk in.\n\nApparently not.\n\nTheir memory may be a bit short, but if their numbers are thinned enough, they'll keep to themselves. Head into the valleys in the north and east and clear out a fair chunk of them for me, will ya?", completion = "It's dirty work, I know, but we appreciate it. Now what was the name the scout mentioned... Sirana?", objectives = "Glorthal Stiffbeard at Frosthold wants you to kill 8 Frostfeather Screechers and 8 Frostfeather Witches.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12867] = { id = 12867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baby Stealers", description = "A few weeks ago, if you looked up, you'd see dozens of those beautiful eagles soaring the skies. Now, only a few if any. They've taken to staying with their nests nearly all the time now because the harpies have been stealing their eggs.\n\nThe harpies have grown a taste for eagle flesh, it seems... the sick wretches are caring for the eggs long enough to feast on the hatchlings. Go into the valleys to the north or the east and find the eggs... bring them back here, and I'll take them back to the nests.", progress = "We'll get this harpy problem taken care of... the eagles will be free to soar the skies again soon.", completion = "Good stuff, lad. You're making fast friends.\n\nIf you stop back by soon, I'm sure we can find one that will let you ride... they should know that you're trustworthy now.", objectives = "Fjorlin Frostbrow at Frosthold would like you to bring back 15 Stormcrest Eagle Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12868] = { id = 12868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sirana Iceshriek", description = "This Sirana Iceshriek sounds like the one that's spurring the harpies to be more aggressive. If we kill her, I suspect their attacks won't last long afterwards.\n\nOne of our stormriders claims to have spotted her circling the peak directly northwest of here.  Go find the wench and put her down. Let's see this done.", completion = "It's done then. Thank you.\n\nI've spoken with Fjorlin - he said that his men will take charge of keeping the harpies down a bit. As long as we don't let up again, they won't find the courage to think they can attack our people.\n\nI know this wasn't the most tasteful work - take this as a token of my appreciation.", objectives = "Glorthal Stiffbeard at Frosthold wants you to kill Sirana Iceshriek.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12869] = { id = 12869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pushed Too Far", description = "You were there with Loken, weren't you? The iron dwarves captured Veranus, the brood mother of the proto-drakes. The drakes don't seem even a little bit happy about the situation... they've gotten very aggressive.\n\nThey've pushed into stormcrest territory and the eagles have taken to an all out fight with them. It's time to return the favor. We're riding to the Foot Steppes and slaughtering them there.\n\nKing Stormheart left this hammer to me - make good use and see to it that I get it back.", progress = "This is completely out of control.", completion = "I don't see the drakes being dissuaded so easily. Stop back by tomorrow if you think you can spare more time to help.", objectives = "Fjorlin Frostbrow at Frosthold wants you to ride with a Stormcrest Eagle and kill 16 Stormpeak Wyrms in the Foot Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12870] = { id = 12870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Relics", description = "Why hello thar!\n\nBefore you be headin' off to do your grand questin' and adventure, might I beg a wee favor of ya, <lad/lass>?\n\nThese mountains be packed full'a precious relics and baubles... this place be a dream come true for tha league. I'd be much obliged if ya could bring any such treasures you stumble upon back ta me. You can even share in me ale for tha trouble! Trust me <lad/lass>, that's a rich deal!", progress = "Did ya find some o' dem relics for me?", completion = "Beaut! Yer a good one you are.\n\nTilt one back wi' me! Let us celebrae' this glorious find!", objectives = "Return 10 Relics of Ulduar to Rork Sharpchin in Frosthold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12871] = { id = 12871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid from the Explorers' League", description = "Interesting. I don't see any locking mechanisms on the shell. That suggests to me that it may take more than just finding the other piece to combine the keystone.\n\nTake the shell back to the expedition leader, Lagnus, at Frosthold. Once he gets over his awe, he should be able to glean what the core looks like based on the shell, and maybe they can get the Frost Dwarves to help find it.\n\nI'm going to see if I can find out how to combine the two pieces. We'll catch up once we've both made some progress.", progress = "Hello there!", completion = "By Muradin's beard! Is that what I think it is?! Brann's really outdone himself this time... and you too for that matter! The boys back home are never going to believe this.", objectives = "Take Norgannon's Shell to Lagnus at Frosthold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12872] = { id = 12872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Norgannon's Shell", description = "Charging inventor's disk.\n\nDisk charging completed.\n\nPreparing emergency protocol gamma.\n\nEmergency protocol loaded. Please use the charged disk to activate the guardian of Norgannon's shell, Archivist Mechaton. The archivist will release the shell once your identity has been verified.\n\nPlease have a pleasant millennium.", progress = "Well, don't just stand there, show me the shell!", completion = "That's it! That's the first half of Norgannon's keystone. Well done, {name}. When I get back to Ironforge, I'm going to have you inducted as an honorary member in the Explorers' League!", objectives = "Recover Norgannon's Shell from Archivist Mechaton.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12873] = { id = 12873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Frostborn King", description = "Definitely... I can see exactly what the core must look like. If any of the frostborn have seen it, they'll be sure to recognize the description.\n\nThere's no time to waste, let's get straight to business. Go talk to King Stormheart and request his aid... he's sure to know someone who can help us find the core. And be nice about it will you - he's very respected around here.", completion = "Norgannon's Core? Never heard of it. I might well know someone that has though.", objectives = "Speak to Yorg Stormheart in Frosthold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12874] = { id = 12874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fervor of the Frostborn", description = "I be more than willing ta lend my shelter and home ta travelers in need, but I'm nae too keen ta force my people inte yer affairs.\n\nI'll tell ye what... my people are warriors, straight and true. On the day a frostborn becomes a man, he has ta prove himself in battle. He has ta show us that he'll not let size hold'm back.\n\nShow me yer as strong and fierce as one of my men, and I'll have them lend ye an ear or a blade. Speak ta Fjorlin over by the cliff to the south there and he'll put ye ta the test.", completion = "Ha! Grand tale lad... perhaps ye have a bit of frostborn blood in ye, eh? Yer not just talk anyway, and that's what I needed to hear.", objectives = "Yorg Stormheart at Frosthold has requested that you speak to Fjorlin Frostbrow to secure a ride and face your challenge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12875] = { id = 12875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Experienced Guide", description = "I don't know where this core is hiding, but ye knew that. I said I'd help though, and that I shall.\n\nThere's a hermit by the name of Drom Frostgrip who lives in a cave north of here... down in tha valley. We've strayed away from the titans a bit ourselves being that there are so few about, but Drom's loyal to the old ways... he keeps an eye on their most precious places and speaks te the keeper Creteus often.\n\nYer sure to find him in the back of his cave... tell'm I sent ye and he'll help ye.", completion = "<Drom coughs up a bit of blood.>\n\nNorgannon's Core, eh? I've spent a fair number of days trying to find anything I could about it myself, but it seems to be one of the relics that's still guarded. With reason I suppose.\n\nIf King Stormheart sent you, he surely must see something noble in ye... and I'm not one to refuse my king.", objectives = "Locate Drom Frostgrip.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12876] = { id = 12876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwelcome Guests", description = "Our scouts have spotted iron dwarves in the valley north of here. I overheard King Stormheart sending you to visit Drom and I'm admittedly a bit worried about'm.\n\nIf you find any iron dwarves when you head down there, put'm down hard and fast for me, eh? I dun think they know exactly where we are or how to get here just yet, and I'd prefer to keep it that way.", completion = "Grim news, lad. Those iron dwarves seem to be increasing in numbers... we've been seeing them all over the mountains. I smell war coming.\n\nThank you for dealing with this bunch... a little more time bought.", objectives = "Fjorlin Frostbrow at Frosthold wants you to kill 10 Stormforged Invaders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12877] = { id = 12877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lonesome Watcher", description = "I never found the core... but I've often spoken to the keeper Creteus, and his omissions give him away. You'll find Creteus over the mountains to the east, in the Foot Steppes, keeping watch on the Engine of the Makers. The core might well be in there, but you'll need to win Creteus's favor.\n\nThe iron dwarves were here looking for something... it might well be the core. They took my ring. Find their leader, get the ring back, and show it to Creteus so that he knows I sent you.", progress = "Hello, {race}.\n\nI am pleased that you have opted to utilize your tongue over your blade when making my acquaintance. I have found that a more and more rare quality among your kind of late.", completion = "Drom's ring? I am to assume Drom is not well if he did not introduce you directly. I am sorry to hear of that. Drom is a noble dwarf, if an inquisitive one.\n\nOn what business have you come then?", objectives = "Recover Frostgrip's Signet Ring from an Iron Dwarf Monitor and then bring it to Creteus in the Foot Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12878] = { id = 12878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hidden Relic", description = "During your absence, I was privileged enough to parley with the dwarf Brann Bronzebeard. This dwarf indicated his purpose for seeking the keystone, and I am satisfied that it is for satisfactory intent... I believe this dwarf may be the entity for which the keystone was created.\n\nNorgannon's Core is located in the Frigid Tomb to the southeast. Its guardians are ancient beings of ice, and they will not welcome your presence. Best these guardians and retrieve the keystone with my blessing, {race}.", completion = "<As the chest opens, air rushes out into the chamber, carrying with it the musty smell of something that has been here for countless years. Norgannon's Core rests in the bottom of the chest, undisturbed by the ages.>", objectives = "Creteus in the Foot Steppes has provided you with the information to locate Norgannon's Core.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12879] = { id = 12879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fury of the Frostborn King", description = "<As you retrieve the core from the chest, you hear the thumping of heavy footsteps rushing towards you from the corridor. There is the faint sound of battle in the distance.>", progress = "Someone is using the Forge of Wills to create this army... Ulduar is no longer safe. {race}, did you recover the core?", completion = "Someone is using the Forge of Wills to create this army... Ulduar is no longer safe.\n\n{race}, I am pleased that you were able to reach the core before these abominations were.", objectives = "Bring Norgannon's Core back to Creteus in the Foot Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12880] = { id = 12880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master Explorer", description = "Combining the keystone will require Norgannon's Binding - a device located in the Engine of the Makers, the large pit beside us. Brann should be down there with the other half of the keystone now. I have instructed him on the use of the device. He awaits your presence.\n\nI will do what I can to keep the iron dwarves occupied, but I do not have confidence that I will hold them for long. King Stormheart is returning to the defense of Frosthold with some of his men shortly. Please hurry, {race}.", progress = "Hey there, lad! Good to meet ya in person. Did you find it?", completion = "You're brilliant, lad! Brilliant! This will be a glorious day indeed.\n\nQuickly, hand me the core before those iron dwarves make their way down here.", objectives = "Bring Norgannon's Core to Brann Bronzebeard in the Engine of the Makers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12881] = { id = 12881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brothers Bronzebeard" }
quests[12882] = { id = 12882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Relics", description = "Welcome to the peaks.\n\nI have a simple request before you head off on whatever grand jaunt you have planned. There are relics and treasures of ancient Ulduar scattered through these mountains. Most are likely in possession of the various sentient races.\n\nReturn any that you find to me, and I will reward you in kind. Perhaps I'll even let you partake on my many potent ales.", progress = "Were you able to find the relics of which I spoke?", completion = "These will do nicely! I am much obliged. Perhaps a drink for your troubles?", objectives = "Return 10 Relics of Ulduar to Olut Alegut at the Grom'arsh Crash-site.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12883] = { id = 12883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orders From Drakuru", description = "Minions be hearin' da call of your masta! Da Lich King be givin' Drakuru full control of da armies of da Scourge in Zul'Drak. We be commanded ta kill everyting.\n\nEVERYTING MUST DIE!\n\nWe be processin' all da corpses in da Dead Fields and sendin' em up ta Prince Navarius' crew in  Zeramas for Scourgin'! Notin' goes ta waste on Drakuru's watch!\n\nSoon we be drinkin' da blood of da prophets ta become stronger dan eva before! Zul'Drak and Gundrak gonna fall to da Scourge!", progress = "Drakuru, eh? I've heard the name before...", completion = "If this is the same Drakuru from Drak'Tharon Keep we are going to need... outside assistance.\n\nDeath knights of Acherus are stationed nearby, undoubtedly following the same trail of Scourge destruction that lead the Argent Crusade here. As half of our army is tied up at the Argent Stand, battling crazed Drakkari trolls, we will have to join forces with the Knights of the Ebon Blade.\n\n<Lantinga mutters under his breath.>\n\nI was hoping I'd never have to see those scoundrels again after Light's Hope...", objectives = "Return the Orders From Drakuru to Crusader Lord Lantinga at Light's Breach in Zul'Drak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12884] = { id = 12884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ebon Watch", description = "West of here, across the ruined roads and structures, is the death knight encampment of Ebon Watch.\n\n<Crusader Lord Lantinga rolls up Drakuru's orders.>\n\nTake these orders and deliver them to Stefan Vadu. He is the death knight in command at Ebon Watch. Let him know that the Argent Crusade will deal with Prince Navarius. They'll have to handle Drakuru.\n\nBe careful, {name}. The way to Ebon Watch is teeming with Scourge.", progress = "What have you got there, {race}?", completion = "<Stefan reads the missive, then crumples it up and tosses it into the fire.>\n\nOld news. The Argent Crusade is - once again - late to the party. We've been tracking Drakuru since Grizzly Hills. He is slated for eradication.", objectives = "Deliver the Orders From Drakuru to Stefan Vadu at Ebon Watch in Zul'Drak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12885] = { id = 12885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Exiles of Ulduar", description = "The Storm Peaks are an intriguing place, but there's far more here than titan ruins. The peoples who live here face a dire threat in Loken and his minions.\n\nHe sent his favorite servants, the iron dwarves, on a brutal campaign against all the creatures of stone. He expelled the earthen from Ulduar, forcing them to take shelter at Bouldercrag's Refuge, on the face of a mountain west of the Inventor's Library. Bouldercrag and his brethren are beset by the iron dwarves there. Find and help them, {name}.", completion = "So you know Brann Bronzebeard, then? He is our closest ally among those of the flesh. We are as brothers in the struggle against Loken and his followers, in the struggle for Ulduar.", objectives = "Speak with Bouldercrag the Rockshaper at Bouldercrag's Refuge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12886] = { id = 12886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Drakkensryd", description = "This is it.  You've passed all the tests of the Hyldsmeet... all but one.  You've risen among our sisters' best and fiercest.\n\nThe final test is at hand.  The Drakkensryd - the true test of a Hyldnir's worth and warrior spirit.  It'll be you, your riding drake, a chained harpoon and a score of your sisters vying for dominance.\n\nShow no quarter.  None will be expected.", completion = "Sif... is that you?", objectives = "Use the Hyldnir Harpoon to defeat 10 Hyldsmeet Drakeriders at the Temple of Storms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12887] = { id = 12887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's All Fun and Games", description = "The Knights of the Ebon Blade want to take the Scourge base known as The Shadow Vault to the northwest. I have a contact in their group who has asked for help.\n\nThe first step is to blind the Lich King. He's using a device known as The Ocular to watch the area, which floats above the vault's spires.\n\nOur dwarves have created something for you to use against it. After the 'eye' has been destroyed, find Baron Sliver on the vault grounds. He's pretending to still be under the Lich King's will.", progress = "The Ocular still stands! Thassarian was a fool to trust you.\n\nWhoever you are, don't return again until it is destroyed. My position here must not be compromised!", completion = "Perhaps now we can really get something done. Don't be fooled though, the Lich King can still 'see' through his Scourge minions.\n\nThat's why you're here.", objectives = "Destroy The Ocular and then report to Baron Sliver at The Shadow Vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12888] = { id = 12888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SCRAP-E", description = "This card allows the user to access the control panel of the scrapbot designated SCRAP-E, in order to perform maintenance and reprogram the bot's directives.\n\nSCRAP-E appears to be assigned to the interior of the building at The Inventor's Library. The card displays a list of the bot's broken components and failing systems. With the proper parts, the bot can be restored to working condition.", progress = "<You open SCRAP-E's access panel.>", completion = "<You begin performing the repairs indicated by the access card. When the repairs are complete, you close the access panel and throw the power switch.>", objectives = "Bring the SCRAP-E Access Card along with 4 Handfuls of Cobalt Bolts and 5 Overcharged Capacitors to SCRAP-E at The Inventor's Library.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12889] = { id = 12889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prototype Console", description = "Designation SCRAP-E.\n\nDirective: Maintain consoles and databases of Inventor's Library in Keeper Mimir's absences.\n\nTime since last maintenance cycle: 489 days.\n\nStatus of schematic data: unknown.\n\nCurrent tasks: Repair prototype console.", completion = "You examine the display on the repaired prototype console. At least one of Mimir's schematics seems to have survived the long period between maintenance cycles. From the diagrams and instructions displayed in the schematic's file, you could easily construct the mechagnome shown.", objectives = "Interact with the Prototype Console in The Inventor's Library.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12890] = { id = 12890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If Size Mattered..." }
quests[12891] = { id = 12891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Have an Idea, But First...", description = "When I was in the - ahem - employ of the Lich King, we would often use a device known as a sovereign rod to keep some of the more intelligent Scourge in line.\n\nI require that you assist me in the construction of a new one.\n\nLuckily for you, all of the necessary components are at hand: a cultist rod, an abomination hook, a geist rope, and a handful of Scourge essences.\n\nThis should not be difficult, {class}.", progress = "When you've managed to acquire that which I have asked of you, I will fashion the device, with a few modifications for our purposes, and we'll be on with our business.", completion = "Quickly, hand them to me and stay out of sight!\n\nThe rod, the hook, and the rope are all very self-evident in their usage when combined. I just need to infuse the result with the essences and we'll be ready to proceed.\n\nIt's all very mundane in its composition, but extraordinary in its application!", objectives = "Baron Sliver at The Shadow Vault has asked you to collect a Cultist Rod, an Abomination Hook, a Geist Rope, and 5 Scourge Essences.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12892] = { id = 12892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's All Fun and Games", description = "The Knights of the Ebon Blade want to take the Scourge base known as The Shadow Vault to the northwest. I have a contact in their group who has asked for help.\n\nThe first step is to blind the Lich King. He's using a device known as The Ocular to watch the area, which floats above the vault's spires.\n\nOur goblins have created something for you to use against it. After the 'eye' has been destroyed, find Baron Sliver on the vault grounds. He's pretending to still be under the Lich King's will.", completion = "Perhaps now we can really get something done. Don't be fooled though, the Lich King can still 'see' through his Scourge minions.\n\nThat's why you're here.", objectives = "Destroy The Ocular and then report to Baron Sliver at The Shadow Vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12893] = { id = 12893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Your Mind", description = "Vile, Lady Nightswood, and The Leaper would make excellent weapons in the fight against the Lich King if they can be broken from his will. That is what the Sovereign Rod is for.\n\nYou'll find them on the ledges to the east and west of the vault, as well as on the mid-tier of the vault above us. The rod is to be used upon the corpses of the three.\n\nFly now. We will have them as our own!", progress = "You have NOT turned them yet. Do not insult my intelligence, {class}!", completion = "We will put those three to good use once we finally take the vault.\n\nSpeaking of which....", objectives = "Baron Sliver at the Shadow Vault wants you to use the Sovereign Rod on the corpses of Vile, Lady Nightswood, and The Leaper.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12894] = { id = 12894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crusader Forward Camp", description = "Crusader Dargath, Crusader MacKellar, Engineer Reed and the twins, Gerk and Burr, were sent to the Dead Fields to establish a battle front days ago. As of my last correspondence with them, they had successfully established a camp on the border of the Dead Fields, northwest of here.\n\nIn light of this newfound information about Drakuru and Prince Navarius I think it would be prudent to send someone to the Crusader Forward Camp post-haste.\n\nPack up your belongings, {name}. You must leave at once!", completion = "Everything was fine until the Scourge attacked. They took off with Dargath, Gerk and Burr and they also destroyed our ride. Guess who led that attack?\n\n<MacKellar nods.>\n\nNavarius...\n\nSeems this whole area is some type of factory for Scourge. We're in the middle of a damned undead mine field!", objectives = "Seek out Crusader MacKellar at the Crusader Forward Camp in Zul'Drak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12895] = { id = 12895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Bronzebeard", description = "Before we left, I received the file Scout Vor'takh compiled on this Brann Bronzebeard. There can be no doubt that Brann was headed for the Storm Peaks from his journal entries and findings in Grizzly Hills. Before we crashed, I caught sight of a campsite south of here, across the Foot Steppes, and overlooking the frozen Bor's Breath River.\n\nIf Brann isn't there, search the camp and its environs for any clues as to where that blasted dwarf might've gone. Bring back anything you find.", progress = "Did you have any luck finding Bronzebeard's camp?", completion = "Of course, with our luck, I probably could've predicted this. Well, we're not going to let him get away that easily. Let's see what that note says.", objectives = "Retrieve the Burlap-Wrapped Note from Brann's camp and return it to Boktar Bloodfury at the Grom'arsh Crash-Site.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12896] = { id = 12896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If He Cannot Be Turned", description = "Death knights, such as General Lightsbane, are held on too tight of a leash to be able to be turned from the Lich King's will except under the most extraordinary circumstances.\n\nThe general keeps himself within the vault overseeing the creation of new weapons. Disturb one of his weapon racks at the northern forge and I assure you, he will come. I'll send Vile, Lady Nightswood, and The Leaper in to help you.\n\nIf we are to finally own The Shadow Vault, General Lightsbane must fall!", completion = "General Lightsbane and his forces are defeated? The Shadow Vault is taken?", objectives = "Defeat General Lightsbane and then report your success back to Thassarian aboard the gunship, The Skybreaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12897] = { id = 12897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If He Cannot Be Turned", description = "Death knights, such as General Lightsbane, are held on too tight of a leash to be able to be turned from the Lich King's will except under the most extraordinary circumstances.\n\nThe general keeps himself within the vault overseeing the creation of new weapons. Disturb one of his weapon racks at the northern forge and I assure you, he will come. I'll send Vile, Lady Nightswood, and The Leaper in to help you.\n\nIf we are to finally own The Shadow Vault, General Lightsbane must fall!", completion = "General Lightsbane and his forces are defeated? The Shadow Vault is taken?", objectives = "Defeat General Lightsbane and then report your success back to Koltira Deathweaver aboard the gunship, Orgrim's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12898] = { id = 12898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow Vault", description = "It sounds like you did extremely well. And you secured three very important allies for the Knights of the Ebon Blade in the process.\n\n<Thassarian gazes out over the horizon.>\n\nYou should head back. By now, Baron Sliver and the other death knights will be fighting tooth and nail to hold The Shadow Vault against the might of the Scourge.\n\nI'm sure they'll need your help.", completion = "Good of you to return. As you can see, we have our hands full here.", objectives = "Report back to Baron Sliver at The Shadow Vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12899] = { id = 12899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow Vault", description = "It sounds like you did extremely well. And you secured three very important allies for the Knights of the Ebon Blade in the process.\n\n<Koltira gazes down at the map on the floor.>\n\nYou should head back. By now, Baron Sliver and the other death knights will be fighting tooth and nail to hold The Shadow Vault against the might of the Scourge.\n\nI'm sure they'll need your help.", completion = "Good of you to return. As you can see, we have our hands full here.", objectives = "Report back to Baron Sliver at The Shadow Vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12900] = { id = 12900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making a Harness", description = "So you want to ride?  Well, if you've made it this far someone must think you've got a shot at the Hyldsmeet.\n\nFirst things first; we'll have to make you a harness.\n\nIn the cliffs to the south, you'll find scattered groups of yeti.  Their hides are tough and just the right thickness.  Bring me some and we'll get you started on the path of the bear-rider.", progress = "Did you find the hides yet?  You'll find yeti in the hills below.", completion = "These will do nicely.  I'll have the harness ready for you in no time.", objectives = "Astrid Bjornrittar in Brunnhildar Village wants you to obtain 3 Icemane Yeti Hides.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12901] = { id = 12901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Something Out Of Nothing", description = "Prince Navarius must be stopped. We can't let the Scourge continue to use this area as a zombie factory. If we can get the tank operational we might stand a chance. What I need right now are spare parts.\n\nNorthwest of here is an area called Thrym's End. The Scourge armies are using the area as a base of sorts. Spread out across the base is the wreckage from their arrival. Bits and pieces of Scourge scrap metal litter the landscape. Get that stuff to me and I'll try and put it to good use.", progress = "I really don't know if this plan will work, {name}. Just bring me the scrap metal and I'll do what I can.", completion = "What is this junk! Ah, damn it all! It's useless. Scourge metal isn't gonna do the trick. What are we going to do?", objectives = "Engineer Reed at Crusader Forward Camp in Zul'Drak has asked that you recover 10 pieces of Scourge Scrap Metal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12902] = { id = 12902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search Of Answers", description = "These poor creatures are the only survivors.\n\nAccording to their chief, the Drakkari trolls and Rageclaw wolvar have been allies for thousands of years. They've been living here, alongside the trolls, for generations, completely unaware of the ever changing world around them. To the Rageclaw, a troll is a troll, so the troll attack upon their den took them by surprise.\n\nWe need some answers, {name}. Scour their village - southeast of here - for clues as to who or what is in charge of these attacks.", completion = "There is a scroll floating in the air above the strange altar. This must be what Crusader Lord Lantinga is looking for!", objectives = "Search Rageclaw Den for a clue about who or what initiated the attacks against the Rageclaw Wolvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12903] = { id = 12903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's What Friends Are For...", description = "We were attacked by Prince Navarius and at least a dozen Scourge. I told Dargath and the twins to stay inside the tank, but they wouldn't listen. Dargath looked me in the eyes and said, \"If somebody doesn't get out of this tank, they'll kill us all.\" He then made Reed cut the engine and charged. Most heroic thing I've ever seen.\n\nI heard the Prince barking orders to the monsters. Sounded like he was taking them to Thrym's End, northwest of here. We have to rescue our friends. Will you go look for them?", completion = "It was a great sacrifice that those three made and it won't soon be forgotten. Their passing will not be in vain. We will be victorious!", objectives = "Crusader MacKellar at Crusader Forward Camp has asked that you find Crusader Dargath, Gerk and Burr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12904] = { id = 12904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light Won't Grant Me Vengeance", description = "They... They killed my brother.\n\n<Gerk fights back tears.>\n\nSlaughtered him like he was some sort of animal. Now they got him laid out on one of their tables on the other side of the camp, ready for their grisly experiments. Dargath's dead too. The paladin made a heroic stand at the ruins to the northeast, but the leader of the Vargul, Algar, was too strong.\n\nI'm all that's left and I'll be dead soon too. I... I'm turning.\n\nIf the Light won't grant me vengeance, maybe you will, {class}. Kill them all.", progress = "You're doing the world a favor, friend. These monsters must be stopped!", completion = "<Gerk is dying.>\n\nTh... They say these Vargul are the... the ones that weren't found worthy by the Lich King. Can... Can you im... imagine it? Just th... think how powerful the... the... worthy must be...\n\nI'll say a prayer for you in the hereafter, hero... May you never have to face them in number.", objectives = "Gerk at Thrym's End in Zul'Drak wants you to kill 15 Vargul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12905] = { id = 12905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mildred the Cruel", description = "Our deal is made then, {name}.  You help me get out of these chains and I'll help you find your little green friend.\n\nThe Hyldnir who runs this mine is known as Mildred the Cruel -- and with good reason.\n\nTell her you've been sent to lend a hand with the mines.  Do whatever she asks until she trusts you with the keys to my shackles.", completion = "I was expecting a replacement for one of my overseers.  It's about time you showed up.\n\nLet's put you to work.", objectives = "Speak to Mildred the Cruel inside the Forlorn Mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12906] = { id = 12906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discipline", description = "Let's start you off with something straightforward.  The male vrykul that work the mines for us do so against their will... purely out of fear of our blades.\n\nOnce in a while, one of them will lose their motivation.  Find any uncooperative vrykul and put them in their place.\n\nTake this disciplining rod.  You'll want to inflict pain, not death.  Well, most of the time anyway.", progress = "Is it done?  I hope you didn't slay too many of the mongrels.  We need the manpower.", completion = "Not bad for a new overseer.  I've another task for you if you're feeling brave today.", objectives = "Mildred the Cruel at the Forlorn Mine wants you to use the Disciplining Rod on 6 Exhausted Vrykul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12907] = { id = 12907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Examples to be Made", description = "For every action there is an opposite reaction, sister.  In the case of us applying pressure on the males, this has meant newly spread rumors of insurrection.\n\nThe bearded pig behind this rabble-rousing is called Garhal.  Put an end to him... and make sure the other males see his demise.  They must learn that insubordination will not be tolerated.", progress = "You're back.  Did you kill the insubordinate pig?", completion = "If I had any reservations regarding your commitment when you first arrived, I no longer have any.  With just a little more effort you could be a permanent member of my operation.", objectives = "Mildred the Cruel at the Forlorn Mine wants you to slay Garhal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12908] = { id = 12908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Certain Prisoner", description = "You are without mercy.  You will do well around these parts.\n\nI have another task to ask of you.  There is a female vrykul prisoner that's become more of a liability than I had anticipated.\n\nShe had the gall to claim the right to take part in the Hyldsmeet, our sacred competition of strength and fighting prowess.\n\nHere's the key to her shackles.  Make it as painless as possible.  She's a female after all, even if not one of us.", progress = "It's about time.", completion = "I knew you'd be back!  Get me out of these shackles and I'll help you find the goblin.", objectives = "Take Mildred's Key to Lok'lira the Crone in the Forlorn Mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12909] = { id = 12909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nose Knows", description = "In order to track down Brann, we're going to need a creature with a keen sense of smell and a good tracking ability. There weren't any hounds on the zeppelin, but I think I have a substitute.\n\nAfter the crash, I sent Khaliisi down the east face of the mountain to start hunting for food. Her cat, Frostbite, excels at tracking prey in the snow. Tell her that she'll have to part with her companion for a while, at least. She can hunt on her own, but we have no other way of catching up to Brann Bronzebeard.", completion = "So Boktar has volunteered Frostbite for an errand, eh? Well, this had better be important. He knows better than to try to separate a hunter from her pet!", objectives = "Speak with Khaliisi at the foot of the mountain east of the Grom'arsh Crash-Site.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12910] = { id = 12910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sniffing Out the Perpetrator", description = "Boktar can have his way this time, but I'll expect him to make it up to me. Don't look at me like that. Boktar may be in command, but no one tells a hunter what to do.\n\n'Put that beast away,' he says. 'Make it stop growling.'\n\nAll of a sudden he changes his mind when it suits him. Next time he complains, Frostbite'll just nip him a bit. Don't worry, she'll do an admirable job tracking your prey. After she locates her target, you're on your own to deal with iron dwarves, or Brann, or whatever you find.", completion = "<An image of a dwarf appears as you activate the communicator. It can only be Brann Bronzebeard.>\n\n<From the look on his face, Brann seems shocked to see you and begins gesturing furiously.>", objectives = "Mount Frostbite and ride her to the source of the scent from Brann's note. Then, recover Brann's Communicator and use it to make contact with Brann Bronzebeard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12911] = { id = 12911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Credit Test", description = "/wave at me and I'll assign 'kill credit to player' to you.", objectives = "/wave at Kill Credit Test", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12912] = { id = 12912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Great Storm Approaches", description = "You are not like the others, little one. You do not reek of the ancient death. Perhaps you can be trusted.\n\nI am Gymer, king of the storm giants. I was lured here by my brother, Thiassi, now an undead servant of the Lich King. By the time I realized that his cry for help was a trap, it was too late. I am now a prisoner of the Scourge and I fear that soon I will suffer the same fate as many of the other storm giants.\n\nFind a way to release me from this cage and I will aid you to the best of my ability.", completion = "A... A storm giant? I don't know about this, {name}. That sounds risky. On the other hand, I don't think we have too many other options.\n\nIf I do this you have to promise me that you will get your giant friend to help us deal with Navarius and his cronies.", objectives = "Gymer, King of Storm Giants, has asked you to find a way to release him from his cage. Speak with Engineer Reed at the Crusader Forward Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12913] = { id = 12913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak Orcish, Man!", description = "<Brann begins gesticulating wildly and rambling in his native language.>\n\nRuk MogOth red a mogoth ta eft Thros-garE Haldir.\n\nKha gor ruk khaz ta ke ruk hrim eft thros-am-kha ruk kost-um havar go kost.\n\nA modoss hine ruk bergum eft thros-am-kha ga eft Haldir ke loch Thon we lo gefrunon ta mitta.\n\n Gar Ruk dagUm loch angor-magi ta har ruk!\n\n<After a few moments, you realize the conversation is going nowhere. Perhaps the shaman, Moteha Windborn, at the Grom'arsh Crash-Site will know what to do.>", completion = "Boktar will not be happy that you didn't find Brann, but at least you didn't come back empty-handed. Now, let's see what we can do about this babbling dwarf.", objectives = "Speak with Moteha Windborn at the Grom'arsh Crash-Site.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12914] = { id = 12914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gymer's Salvation", description = "Now you say that he's locked up in a 100 foot tall cage, eh?\n\nIf my calculations are correct, we should be able to at least weaken the hinges on the cage, giving the giant enough leeway to break out.\n\nIf this is going to work I'm going to need some plasticizers and stabilizers.\n\nBanshee essence should do nicely for the plasticizer. You can get that from the banshees in the Dead Fields, northeast of us. The stabilizer can be found on the earthragers to the southwest, near Ebon Watch.\n\nGet a move on!", progress = "Without the plasticizers and stabilizers I'll never be able to make the explosives necessary to break your friend out of jail.", completion = "Thankfully we weren't in short supply of explosives. Putting together the jumbo seaforium charge should be no problem with the materials you brought me.", objectives = "Engineer Reed at Crusader Forward Camp in Zul'Drak wants you to bring him 6 Banshee Essence and 6 Diatomaceous Earth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12915] = { id = 12915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mending Fences", description = "If I hope to wrest control of the Temple of the Makers from my brother, I must make amends with my old allies.\n\nPerhaps by eliminating a common enemy, we may at least take a step towards renewing my friendship with the frost giants.\n\nFjorn has besieged Dun Niffelem with giants of iron. You must defeat him at Fjorn's Anvil, far to the east of here, and weaken his forces sufficiently for the Sons of Hodir to emerge victorious.\n\nTake this charm, {name}. Use it to summon my earthen to your aid.", completion = "So, it is done then.\n\nLet us hope it is enough.", objectives = "Thorim at the Temple of Storms wants you to Kill Fjorn and 5 Stormforged Iron Giants at Fjorn's Anvil, east of Dun Niffelem.\n\nUsing Thorim's Charm of Earth will summon his Earthen to fight by your side. The charm requires a Granite Boulder from nearby Fjorn's Anvil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12916] = { id = 12916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Only Hope", description = "What I'm about to give you is called seaforium. It is a highly volatile explosive with some unique properties. Due to its malleable nature, you will be able to fill in the hinges and cracks of the cage for maximum damage.\n\nReturn to your friend and use the jumbo seaforium charge to set him free.\n\nLet's hope he honors the bargain. He's our only hope.", progress = "I am a giant of my word, little one.", completion = "FREEDOM!\n\nDo not be afraid, little one. Gymer is an honorable giant. Like you and your people, I too wish to see the Scourge driven away from this land and the Lich King destroyed. I will help you, as promised, to the best of my ability.", objectives = "Speak to Gymer at Thrym's End in Zul'Drak once you have used the Jumbo Seaforium Charge to open the Scourge Enclosure that is holding him prisoner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12917] = { id = 12917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speaking with the Wind's Voice", description = "I suppose we shouldn't have expected to find Brann so easily, not with our luck. If we can make sense of what Brann is saying, you can persuade him to give up his location.\n\nThe power of the wind is strong in these mountains, and it may prove a great boon to us. A knowledgeable shaman can hear the sound of all the world's tongues on the wind.\n\nTo the northwest, on the Snowdrift Plains, you will find beings made of wind, the stormriders. Capture their voices and bring them to me.", progress = "Have you brought the wind's voices?", completion = "You should be able to communicate with the dwarf now. Ask Boktar what he requires of you. There is little time to lose.", objectives = "Bring 5 Voices of the Wind to Moteha Windborn at the Grom'arsh Crash-Site.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12918] = { id = 12918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gem Perfection", description = "It has the cold of the Icewyrm's breath up here does it not?   Not only do I lack customers for my crafting skills, but I also lack stock of gems to sell!   If you can bring me several uncut gems to replenish my stocks, I can teach you the skill of gem perfection.   This will allow you to sometimes cut a perfect gem with increased bonuses when cutting a uncommon quality gem from Northrend.You will learn:", objectives = "Return two Huge Citrines, two Dark Jade and two Shadow Crystals to Ounhulo in Valgarde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12919] = { id = 12919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Storm King's Vengeance", description = "My people have been decimated by the Lich King. The Scourge now use the corpses of storm giants to create mindless flesh giants, or worse, stitched together aberrations like Thrym.\n\nI will stop at nothing to see them all driven from this world. We will work together to destroy the Scourge that threaten Zul'Drak.\n\nWe will kill them all: Navarius, Algar and Thrym!\n\nWhen you are ready, let me know and we will begin our destructive journey.", completion = "Unbelievable! This will be a story for the ages, {name}! One man rode upon the head of the king of storm giants and decimated an entire Scourge army!\n\nAnd I was there to see it all happen...", objectives = "Speak with Gymer to begin.\n\nWhile riding Gymer, destroy 100 Scourge and kill Algar the Chosen, Thrym and Prince Navarius. Report to Crusader MacKellar at Crusader Forward Camp should you succeed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12920] = { id = 12920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catching up with Brann", description = "What are you waiting for? The language barrier has been broken, thanks to Moteha. Contact Brann Bronzebeard and find out anything you can about where he's hiding and what he's chasing after.\n\nMaybe we can still salvage something from this disaster.", completion = "<Boktar listens as you describe your conversation with Brann.>\n\nThere's truth to the dwarf's words. Vor'takh's plan is not the way of the Horde. If Brann Bronzebeard knows of a way to stop these iron dwarves and their patron, it serves us to help him.", objectives = "Use Brann's Communicator to contact Brann Bronzebeard and speak with him, then speak to Boktar Bloodfury at the Grom'arsh Crash-Site.\n\nIf you lose Brann's Communicator, speak with Moteha Windborn at the Grom'arsh Crash-Site.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12921] = { id = 12921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Change of Scenery", description = "Excellent.  There's an exit in the eastern end of the mine that leads to Brunnhildar Village.  Follow it and I'll meet you there.\n\nWe must not be seen together so no one suspects you of aiding me.  I'll use my magic to disguise my appearance.  Do not worry, {race} -- we'll find your friend in no time.", completion = "You're here -- good.  I think I know where your goblin is.", objectives = "Reconvene with Lok'lira the Crone in Brunnhildar Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12922] = { id = 12922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Refiner's Fire", description = "Beneath its porous exterior, this hunk of metal gleams with a mysterious quality.\n\nYou feel it would only be prudent to burn off the slag at Fjorn's Anvil.\n\nAs you ponder where in this frozen waste you might find something hot enough for the job, a fire revenant crosses your path...", progress = "The surface of the anvil is scalding, in sharp contrast with the wintry air.", completion = "You place the metal on the anvil and immediately upon adding the sparks they work the ore furiously.\n\nWhen at last they burn out, you are left with a large piece of metal that gleams with a light of its own.", objectives = "You must collect 10 Furious Sparks from the Seething Revenants at Frostfield Lake and then use the anvil at Fjorn's Anvil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12924] = { id = 12924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging an Alliance", description = "<Thorim, for the first time since your meeting him, smiles.>\n\nThis is all beginning to have the smell of fate's hand, {race}.\n\nYour discovery is what remains of my armor, long ago cast off in a fit of grief and left to the elements. Only the sons of Hodir are capable of its reforging, for they are its original creators.\n\nPerhaps you've done enough to soften their hatred of me. Seek out their king, Jokkum, if he still breathes.\n\nFind your way into his good graces and plead for his assistance.", completion = "It would seem that I have refined my technique considerably. That, or the legends surrounding this anvil are true.\n\nThis suit of armor is superior to the last, and took less material to create.\n\nWith the excess, I was able to fashion you a little something as payment for your assistance.", objectives = "You are to go to Dun Niffelem and ask King Jokkum to allow Thorim's armor to be reforged. After completing Jokkum's task, you are to speak with Njormeld in Dun Niffelem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12925] = { id = 12925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aberrations", description = "The Lich King sent emissaries to us on three different occasions.  All three were promptly dismembered.\n\nOur sisters in Valkyrion were not as dedicated to our traditions and accepted the Scourge's advances.  Now instead of capturing their drakes from the wild, they raise them from the blight and filth that the Scourge wallow in.\n\nTake the frost oil that the Valkyrion Hyldnir carry on them and use it to freeze any blighted eggs you find.  Rumors speak of a fetid pool of blight where the eggs are kept.", completion = "You have our thanks, sister.  We cannot allow our valiant traditions to be corrupted.", objectives = "Thyra Kvinnshal in Brunnhildar Village wants you to go to Valkyrion and obtain Vials of Frost Oil from the Valkyrion Aspirants. Use the Vials of Frost Oil to destroy 30 Plagued Proto-Drake Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12926] = { id = 12926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pieces of the Puzzle", description = "We've seen the iron dwarves and their constructs making war on the creatures of stone that Brann calls the earthen, along with their giant allies. Contact him and aid him in any way you can, and remember that anything we can learn from his search may aid us in fighting against the iron dwarves and their master.", progress = "Did you complete the disk?", completion = "That was quick! Now that we have the disk, we have to find out how to use it to unlock the first half of the archive key.", objectives = "Use Brann's Communicator to contact Brann Bronzebeard and find out what to do next.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12927] = { id = 12927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Data Mining", description = "That disk you assembled... it's blank! Keeper Mimir, the tinker who built this library, must've hidden the information elsewhere. Look around the Inventor's Library; do you see any databanks there?\n\nThat might be the disk's purpose. Try using it near some of those databanks. Perhaps it's set to retrieve and store information from them. After you've tried your hand at that, contact me again and let me know what you've found. Meanwhile, I'll be trying to track down the other half of the archive key.", progress = "Did you try using the disk? What did you find?", completion = "<Brann looks at the disk as you hold it up.>\n\nI can't tell if there's anything stored there or not, lad. You'll have to tell me what happened.\n\n<You describe the data retrieval process.>\n\nSo it worked? At least we can count on Keeper Mimir to be systematic.", objectives = "Use the Inventor's Disk to retrieve 7 pieces of Hidden Data from the Databanks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12928] = { id = 12928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Norgannon's Shell", description = "Charging inventor's disk.\n\nDisk charging completed.\n\nPreparing emergency protocol gamma.\n\nEmergency protocol loaded. Please use the charged disk to activate the guardian of Norgannon's shell, Archivist Mechaton. The archivist will release the shell once your identity has been verified.\n\nPlease have a pleasant millennium.", progress = "Did you find Norgannon's shell?", completion = "That's it! That's the first half of Norgannon's keystone. Well done, {name}. I've had Archaeologist Andorin on the lookout for clues to the shell's whereabouts for a long time. He's never going to believe me when I tell him it was an intrepid {race} who found it instead.", objectives = "Recover Norgannon's Shell from Archivist Mechaton.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12929] = { id = 12929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Earthen of Ulduar", description = "The earthen who once inhabited, built, and maintained Ulduar were ousted from their home when Loken took over the city. Since then, his iron dwarf followers have relentlessly attacked the exiles.\n\nThey have taken refuge in an old titan building, which they now call Bouldercrag's Refuge, on the face of a mountain west of the Inventor's Library. Bouldercrag and his brethren fight to keep the irons from overrunning their haven, but they cannot hold their ground long. Find and help them, {name}.", completion = "So you know Brann Bronzebeard, then? He is our closest ally among those of the flesh. We are as brothers in the struggle against Loken and his followers, in the fight for Ulduar.", objectives = "Speak with Bouldercrag the Rockshaper at Bouldercrag's Refuge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12930] = { id = 12930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Earth", description = "It seems so long ago that these hammers pounded and hewed stone instead of iron. Our expulsion from Ulduar saw the weakest of us dead and the strongest of our craftsmen reborn as warriors.\n\nAs the irons beat us back, even the strongest find themselves failing.\n\nWe can do little for the wounded, save when we have a stock of enchanted earth. We used to mine it from the deposits on the sheer cliff face to the northwest, but the constant battle has prevented us from replenishing our stock. Would you help?", progress = "Were you able to find any of the earth?", completion = "This will allow us to patch up more of the fallen. Thank you, {name}, on behalf of all who defend the refuge.", objectives = "Use the Earthen Mining Pick to mine 7 clumps of Enchanted Earth. Bring the earth and 5 Frostweave Cloth to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12931] = { id = 12931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fighting Back", description = "The refuge's defenders have done their best to blunt the iron dwarves' attacks, but we keep losing ground inch by inch. My men are hardy, but not tireless. Without reinforcements, it's only a matter of time until we will be overrun.\n\nWould you lend your skills to the refuge's defense? It would greatly improve the morale of the defenders and give them -- and me -- hope of mounting a counterattack.\n\nKill any of the stormforged or their creations you encounter outside the refuge.", completion = "You've given the defenders something to cheer about. Seeing the enemy fall by your hand has reinvigorated them and bolstered their courage.", objectives = "Bouldercrag the Rockshaper wants you to slay 10 Stormforged Attackers and return to him at Bouldercrag's Refuge. You may kill either Stormforged Raiders or Stormforged Reavers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12932] = { id = 12932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amphitheater of Anguish: Yggdras!", description = "I'll tell you what, buddy, this place is a far cry from the rolling plains of Nagrand. These trolls are dirtier than ogres; but hey, I go where the gold's at! So welcome to Zul'Drak, pal.\n\nYou're new to this racket, so let me set you straight. I'm the fight promoter and this feisty troll next to me is Wodin, my bodyguard. You're the entertainment. When you wanna fight, let me know and I'll set up the match.\n\nIf you're ready and got a group of friends with you, we can start! What do you say?", progress = "No payout until the fight's over, man.", completion = "Not bad, friend. You might make some gold out here - if you manage to stay alive.", objectives = "Get in the arena at the Amphitheater of Anguish and defeat Yggdras! Return to Wodin the Troll-Servant to redeem your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12933] = { id = 12933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amphitheater of Anguish: Magnataur!", description = "This next match is a doozy, buddy! Apparently some magnataur from the Dragonblight wants a piece of the action. You ever fought one of those before? All I can tell you is to aim high!\n\nWe'll get this party started when you give me the word.", progress = "No payout until the fight's over, man.", completion = "Wow! When I first saw Stinkbeard, I thought you were done for! Nice work!", objectives = "Get in the arena at the Amphitheater of Anguish and defeat Stinkbeard! Return to Wodin the Troll-Servant to redeem your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12934] = { id = 12934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amphitheater of Anguish: From Beyond!", description = "I'm not gonna lie to you, pal. You might be overmatched here. This next one is a being from the elemental planes! I don't even know what's gonna show up in that arena!\n\nIf you think you're up to it, get in there and give 'em hell!", completion = "Unbelievable! I thought this whole place was going to explode when it first appeared! You really dominated that round!", objectives = "Get in the arena at the Amphitheater of Anguish and defeat one of the elemental lords! Return to Wodin the Troll-Servant to redeem your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12935] = { id = 12935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amphitheater of Anguish: Tuskarrmageddon!", description = "This next one's fightin' from a dark place, kid. The kind of dark that can only happen when you've been on the flip-side. He's hungry and willing to do whatever it takes to win. Watch yourself! I've heard he wrestles yetis for exercise!\n\nWe'll start when you're ready.", completion = "I was worried for a while there, {name}. When he busted out the seals and penguins... Well, I didn't know what to think to be honest. It looked pretty damn ridiculous.", objectives = "Get in the arena at the Amphitheater of Anguish and defeat Orinoko Tuskbreaker! Return to Wodin the Troll-Servant to redeem your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12936] = { id = 12936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amphitheater of Anguish: Korrak the Bloodrager!", description = "You're not gonna believe this, pal. Your next fight is against Korrak the Bloodrager! Looks like the Drakkari trolls are pulling a power play! And let me tell you, buddy, he's been sippin' the animal god juice. He's good and ready to pound you into the ground.\n\nAre you ready?", progress = "No payout until the fight's over, man.", completion = "Damn, I remember Korrak from way back in my younger days when I used to work for the Frostwolf Clan. He would never shut up! I think you just did the world a great service, {name}.", objectives = "Get in the arena at the Amphitheater of Anguish and defeat Korrak the Bloodrager! Return to Wodin the Troll-Servant to redeem your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12937] = { id = 12937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relief for the Fallen", description = "The refuge's defenders fight bravely, but they cannot keep up with the iron onslaught.\n\nWith the earth you collected, I can make bandages to help heal the wounds of some of the fallen. The more defenders we can patch up, the longer we'll last out there.\n\nTake these poultices and use them to heal the wounds of the fallen defenders outside the refuge. Get as many back into the battle as possible, {name}. Every casualty is one too many.", completion = "The warriors that you've healed will aid us in holding the line even longer. If we are to truly be free of the iron threat, we must find a way to strike at them behind the lines.", objectives = "Use the Telluric Poultice to heal 8 Fallen Earthen Defenders, then return to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12938] = { id = 12938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Duke", description = "We need you focused, {name}. We're barely holding The Shadow Vault as it is. As you can see, we've greatly angered the Lich King.\n\n<The baron chuckles.>\n\nI need you to speak with Duke Lankral. He's in charge here now. You'll find him inside the vault building proper.\n\nWere I you, I would not keep him waiting.", completion = "It's a pleasure to finally meet you, {name}. We owe you a great deal, but we're not done with you yet.\n\nThere is a vrykul city just over the mountains to the west, a place called Jotunheim.\n\nThe vrykul there are in a constant state of challenge to 'ascend'. The winners go to Ymirheim to serve as the Lich King's elite warrior caste, the Ymirjar, and the losers are reduced to scourged Vargul.\n\nYou are going to be my instrument to see to it that more Vargul than Ymirjar emerge.", objectives = "Speak with Duke Lankral at The Shadow Vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12939] = { id = 12939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor Challenge", description = "The first step we're going to take is at a place in Jotunheim called the Savage Ledge. It's just over the mountains to the west.\n\nOn the ledge the vrykul warriors are always sparring, being instructed in the finer arts of battle by their thane's men.\n\nI want you to take this flag and issue a challenge to a number of them. Let's demoralize them with the 'mere' skills of a {race}, shall we?\n\n<The duke grins, his rotting teeth flashing in the dim light of the vault.>", completion = "Already I'm hearing reports of the prowess you displayed on the Savage Ledge. Excellent, {name}... excellent!\n\n\n\nAnd now I think it's time to issue a decree to the thane of those vrykul that you so easily defeated.", objectives = "Duke Lankral at The Shadow Vault has asked you to use the Challenge Flag to challenge and defeat 6 Mjordin Combatants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12940] = { id = 12940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12941] = { id = 12941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12942] = { id = 12942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Off With Their Black Wings", description = "Traitors.  We Hyldnir have little love for them.\n\nThe dwellers of Valkyrion have gone unpunished for far too long.  While we remained loyal to Thorim, they became the Lich King's lapdogs!\n\nThey call the ones who receive his gift val'kyr.  They fly on feathered wings, like the harpies they are.\n\nYou will find Valkyrion far to the northwest, beyond the Temple of Storms.  Slay these winged she-wolves, sister.  Slay them and I will reward you with one of my most prized possessions.", completion = "The val'kyr are nothing but the Lich King's lapdogs.  They will be put down like the scum they are.  They've made their choice, now they have to live with the consequences.", objectives = "Iva the Vengeful in Brunnhildar Village wants you to go to Valkyrion and slay 12 Nascent Val'kyr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12943] = { id = 12943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow Vault Decree", description = "Thane Ufrang the Mighty sits within his hall overlooking the Savage Ledge. I've studied him. The thane is a patient vrykul, with a head for strategy and warfare. He's also shown a penchant for biding his time and not wanting to overplay his hand in the ongoing battle.\n\nI need him dead!\n\nI've written a decree. Stand before the thane and read it aloud.\n\n<The duke arches his eyebrow in amusement.>\n\nIt should... unnerve him at the least.", completion = "<Duke Lankral nods his approval at your report of success.>\n\nWe face a foe that dwarfs us, not only in stature, but also numerically. If we are to win the battle for Icecrown, we must outthink them!\n\nWith Ufrang dead, that gives us an advantage in Jotunheim. Let us see if we can capitalize on it.", objectives = "Duke Lankral at The Shadow Vault has ordered you to read the Shadow Vault Decree in the presence of Thane Ufrang the Mighty, and then to slay him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12944] = { id = 12944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
