quests[12946] = { id = 12946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12947] = { id = 12947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12948] = { id = 12948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Champion of Anguish", description = "This is the end, my friend! Your last opponent is going to be your greatest challenge. He's a vrykul champion from the steppes of Icecrown and he's out for blood! Defeat him and you'll be crowned the champion of the Amphitheater of Anguish! This fight is going to make us both rich!\n\nLet me know when you're ready and we'll start.", progress = "No payout until the fight's over, man.", completion = "You did it, {name}! That was the most exciting fight yet! What are you going to do with your winnings? Me? I'm going to Dalaran and blowing it all in the Underbelly. Lot of hot action going on down there!", objectives = "Get in the arena at the Amphitheater of Anguish and defeat Vladof the Butcher! Return to Wodin the Troll-Servant to redeem your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12949] = { id = 12949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get the Key", description = "{class}, the key to my shackles is hanging around the neck of Instructor Hroegar outside.\n\nPerhaps you could retrieve it by separating his head from his shoulders?", progress = "Do you have it?", completion = "Thank you, {race}. Just hand me the key, I'll take care of it myself.", objectives = "Vaelen the Flayed at Ufrang's Hall has asked you to retrieve the Key to Vaelen's Chains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12950] = { id = 12950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12951] = { id = 12951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let the Baron Know", description = "The most important thing that you can do right now is to return to The Shadow Vault and let Baron Sliver know that I've failed.\n\nYou see, I wasn't the only one captured by these vrykul devils. My entire contingent of death knights was also taken.\n\nI should have seen the trap before it was sprung, but there's no use crying over spilled milk now is there?\n\nGo on before you get captured, too! I'll see you back at the vault.", completion = "What?! We can ill-afford to lose one death knight, let alone an entire contingent!!!", objectives = "Speak with Baron Sliver at The Shadow Vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12952] = { id = 12952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gem Perfection", description = "My skills are going to waste in this wretched place.   I spent many years learning to cut gems into their perfect form and have nothing to work on!   You look like the type who may be able to find me some gems and if you do I can teach you the skill of gem perfection.   This will allow you to sometimes cut a perfect gem with increased bonuses when cutting a uncommon quality gem from Northrend.You will learn:", objectives = "Return two Huge Citrines, two Dark Jade and two Shadow Crystals to Carter Tiffens in Vengeance Landing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12953] = { id = 12953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valkyrion Must Burn", description = "The crate is filled with incendiary harpoons.  You recall seeing harpoon guns and dry stacks of hay outside.\n\nPerhaps Iva will appreciate the extra effort and reward you appropriately.", completion = "Now that is what I call dedication!  Those traitors might have a new master now, but they'll never forget their sisters' parting gift.", objectives = "Use the Valkyrion Harpoon Guns to burn 6 Dry Haystacks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12954] = { id = 12954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amphitheater of Anguish: Yggdras!", description = "I was wondering when you'd show up, {name}! Having a past champion of the Ring of Blood here will be a huge draw! We're gonna be rich, buddy! RICH!\n\nAnyway, this dump is Zul'Drak. All the ice trolls seem to use it as a toilet. I dunno, the whole place is off its rocker if you ask me! Who cares, though, right? We're here to make some gold!\n\nYou know the drill, {name}. When you're ready let me know and we'll get this show on the road!", progress = "No payout until the fight's over, man.", completion = "Hey! I know you. Your victory at the Ring of Blood was talked about for months! Too bad you forfeited the championship when you failed to show up to defend your title! Easy come, easy go, eh? At least you're still alive.", objectives = "Get in the arena at the Amphitheater of Anguish and defeat Yggdras! Return to Wodin the Troll-Servant to redeem your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12955] = { id = 12955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eliminate the Competition", description = "Mrrfrmrfrrmrrr...\n\n<The Leaper clears his throat.>\n\nSorry about that. It can sometimes be hard to understand what I'm saying. You know how it is.\n\nI wanted to make sure that if you find yourself at the Savage Ledge, over the mountains to the west, that you make sure to eliminate the competition there.\n\nSpecifically, I'd like you to challenge to duels and humiliate Sigrid Iceborn, Efrem the Faithful, Onu'zun, and Tinky Wickwhistle in front of the vrykul.", completion = "That was important, {name}. By driving them off, you're keeping them from interfering with whatever we need you to do over there.", objectives = "The Leaper at The Shadow Vault wants you to duel and defeat Sigrid Iceborn, Efrem the Faithful, Onu'zun and Tinky Wickwhistle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12956] = { id = 12956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Spark of Hope", description = "Clearly, this is more than an ordinary hunk of metal.\n\nUnlike any ore you're familiar with, it is hard but not brittle, far lighter than it looks, and glows even when cool.\n\nLooking closer, you can make out one of Thorim's runes shining beneath the surface....", progress = "What have you there, little one?", completion = "You notice Thorim's stern countenance brighten with recognition as you present the ore.", objectives = "You are to bring the Refined Gleaming Ore to Thorim in the Temple of Storms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12957] = { id = 12957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slaves of the Stormforged", description = "To the southwest, on the western side of the Snowdrift Plains, the iron dwarves have dug a mine into the hillside. There, they use captive mechagnomes, servants of Keeper Mimir, to mine ore.\n\nI don't know where these mechagnomes came from, nor what they would do with their freedom, but perhaps we can win their help.\n\nGo to the Frozen Mine, {name}, and set these creatures free from their bondage. Ask if they would fight alongside us against iron dwarf tyranny.", progress = "Have you freed the slaves of the stormforged?", completion = "I had hoped that more of the captives would choose to join us, but I do not blame them. Willing allies are few and far between, and we are thankful that you have lent your blade to our cause.", objectives = "Bouldercrag the Rockshaper at Bouldercrag's Refuge wants you to free 6 Captive Mechagnomes and kill 3 Stormforged Taskmasters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12958] = { id = 12958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipment: Blood Jade Amulet", description = "A wealthy shipping concern has requested a collection of Blood Jade Amulets to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.", progress = "Do you have a Blood Jade Amulet for my Undermine shipment?", completion = "Here is your Dalaran Jewelcrafter's Token as promised.  Come back tomorrow and I am sure I will have another item I need from you!", objectives = "Combine a Vrykul Amulet, a Dark Jade and a Bloodstone to make a Blood Jade Amulet and bring it to Timothy Jones in Dalaran.\n\nYou can find a Vrykul Amulet on any Northrend Vrykul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12959] = { id = 12959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipment: Glowing Ivory Figurine", description = "A wealthy shipping concern has requested a collection of Glowing Ivory Figurines to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.", progress = "Do you have a Glowing Ivory Figurine for my Undermine shipment?", completion = "Here is your Dalaran Jewelcrafter's Token as promised.  Come back tomorrow and I am sure I will have another item I need from you!", objectives = "Combine Northern Ivory, a Chalcedony and a Shadow Crystal to create a Glowing Ivory Figurine and bring it to Timothy Jones in Dalaran.\n\nYou can find a Northern Ivory on any Shoveltusk or Mammoth in Northrend.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12960] = { id = 12960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipment: Wicked Sun Brooch", description = "A wealthy shipping concern has requested a collection of Wicked Sun Brooches to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.", progress = "Do you have a Wicked Sun Brooch for my Undermine shipment?", completion = "Here is your Dalaran Jewelcrafter's Token as promised.  Come back tomorrow and I am sure I will have another item I need from you!", objectives = "Combine an Iron Dwarf Brooch, a Huge Citrine and a Sun Crystal to create a Wicked Sun Brooch and bring it to Timothy Jones in Dalaran.\n\nYou can find an Iron Dwarf Brooch on any Northrend Iron Dwarf.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12961] = { id = 12961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipment: Intricate Bone Figurine", description = "A wealthy shipping concern has requested a collection of Intricate Bone Figurines to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.", progress = "Do you have an Intricate Bone Figurine for my Undermine shipment?", completion = "Here is your Dalaran Jewelcrafter's Token as promised.  Come back tomorrow and I am sure I will have another item I need from you!", objectives = "Combine a Proto Dragon Bone, a Sun Crystal and a Dark Jade to craft an Intricate Bone Figurine and bring it to Timothy Jones in Dalaran.\n\nYou can find a Proto Dragon Bone on any Northrend Proto Dragon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12962] = { id = 12962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipment: Bright Armor Relic", description = "A wealthy shipping concern has requested a collection of Bright Armor Relics to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.", progress = "Do you have a Bright Armor Relic for my Undermine shipment?", completion = "Here is your Dalaran Jewelcrafter's Token as promised.  Come back tomorrow and I am sure I will have another item I need from you!", objectives = "Combine an Elemental Armor Scrap, a Bloodstone and a Huge Citrine to craft a Bright Armor Relic and bring it to Timothy Jones in Dalaran.\n\nYou can find an Elemental Armor Scrap on any Northrend Revenant.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12963] = { id = 12963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipment: Shifting Sun Curio", description = "A wealthy shipping concern has requested a collection of Shifting Sun Curios to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.", progress = "Do you have a Shifting Sun Curio for my Undermine shipment?", completion = "Here is your Dalaran Jewelcrafter's Token as promised.  Come back tomorrow and I am sure I will have another item I need from you!", objectives = "Combine a Scourge Curio, a Sun Crystal and a Shadow Crystal to make a Shifting Sun Curio and bring it to Timothy Jones in Dalaran.\n\nYou can find a Scourge Curio on any Northrend Scourge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12964] = { id = 12964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Ore", description = "At the Frozen Mine in the western part of the Snowdrift Plains, the stormforged iron dwarves have constructed a mine manned by slaves.\n\nIt's well behind the lines, so we haven't been able to find out much about what's going on there, but my scouts have reported seeing them remove cartloads of dark, sickly looking ore.", progress = "What have you discovered about the ore?", completion = "<Bouldercrag reaches out to take the ore, but then recoils.>\n\nThat ore... I can't touch it. It seethes with unnatural energy. No creature of stone can handle it. What do they mean to do with this?", objectives = "Bring 5 Ore Samples to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12965] = { id = 12965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gifts of Loken", description = "The one who commands the stormforged iron dwarves is called Runeseer Valduran. Although I have never seen them, it is said that his master, Keeper Loken, who took over Ulduar, has given Valduran powerful titan artifacts.\n\nIt could explain the strength and ferocity my men see in the stormforged warriors.\n\nValduran's base, Nidavelir, lies to the southwest, across the Snowdrift Plains. Go there, {name}, and neutralize his power. Destroy these gifts of Loken's and help us to sap the strength of his followers.", completion = "<Bouldercrag nods grimly.>\n\nYou've weakened the stormforged considerably, but they'll keep fighting. Their casualties matter nothing to them, while our defenders continue to fall. Even if it costs them a hundred or a thousand iron corpses, they'll keep fighting until we've been pounded to gravel.", objectives = "Destroy Loken's Fury, Loken's Power, and Loken's Favor, and return to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12966] = { id = 12966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Can't Miss Him", description = "<Jokkum listens patiently to your request, then ponders it carefully before responding.>\n\nSo it is you we have to thank for Fjorn's demise?\n\nWhile it's true that you have aided us in our time of need, there is still much that must be done to repair our relations with Thorim.\n\nFor now, I shall allow Njormeld to reforge the armor we gifted to the Stormlord so many ages ago. Consider it payment for your assistance against Fjorn.\n\nNjormeld was sent to recover Fjorn's anvil. You should find him there.", completion = "Reforging Thorim's armor? It can be done.\n\nFirst though, there's the matter of the anvil...", objectives = "King Jokkum in Dun Niffelem wants you to find Njormeld at Fjorn's Anvil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12967] = { id = 12967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battling the Elements", description = "Snorri was once the pride of our nation. A mighty warrior, many an enemy fell to his club.\n\nWe honor him, though he's no longer what he once was. Age has taken its toll, dulling his senses and sapping his strength. Still, he remains as proud as ever, never missing an opportunity to join a battle.\n\nSpeaking of battle, we're cooling Fjorn's anvil so it can be taken home. The remaining fire revenants are putting up some resistance. Help Snorri relive his glory days, {race}. Guide him against this enemy.", progress = "Were you able to lead Snorri to another victory, {class}?", completion = "An honorable performance, {race}. I shall inform the king of your assistance.\n\nThe anvil is nearly cool enough. I shall see you in Dun Niffelem soon.", objectives = "Njormeld wants you to accompany Snorri to Fjorn's anvil and help him kill 10 Seething Revenants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12968] = { id = 12968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yulda's Folly", description = "The witch that started it all, Yulda the Stormspeaker came to our very village.  She dared to insult our noble traditions and spouted the Lich King's venomous promises of power.\n\nShe ought to have left with a sword through her, but her magic was strong and she managed to escape.\n\nSeek her in Valkyrion inside the largest dwelling and show her that we are not to be trifled with.", completion = "Yulda had it coming.  No one gets away with insulting the Hyldsmeet.  Not even one of our own.", objectives = "Iva the Vengeful at Brunnhildar Village wants you to slay Yulda the Stormspeaker in Valkyrion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12969] = { id = 12969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Is That Your Goblin?", description = "I trust that's the green little one you've been looking for.  If I were you I'd step in before that Hyldnir splits him in half.\n\nYou've arrived in the middle of the Hyldsmeet, so all challenges must be accepted by participants.  There's nothing to stop you from taking your green friend's place.", progress = "You're back.", completion = "Well done, young one.  It looks like our deal has been satisfied on both our ends.", objectives = "Challenge Agnetta Tyrsdottar in order to save Zeev Fizzlespark. Return to Lok'lira the Crone in Brunnhildar Village after you've succeeded.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12970] = { id = 12970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hyldsmeet", description = "Whether you've noticed or not, by defeating your first Hyldnir in hand-to-hand combat, you've entered the Hyldsmeet -- the great competition of Hyldnir against Hyldnir to determine who will rule by Thorim's side.\n\nThe Hyldsmeet is the reason why I was imprisoned, for I sought to partake in the competition but was far too old and frail to be a match for the Hyldnir.\n\nIf you're willing to listen, I've a proposal for you.", completion = "It's settled then.  You will compete in the Hyldsmeet and with my help you'll restore great Thorim to his rightful place.", objectives = "Listen to Lok'lira the Crone's proposal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12971] = { id = 12971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking on All Challengers", description = "Let's get you started.  The good news is that by defeating Agnetta, you've earned yourself a spot in the next round of matches.\n\nThe bad news is that all your opponents will also have defeated someone in the first round.  Do not expect pushovers.", completion = "You've done it, {name}.  You've bested some of the fiercest fighters the Hyldnir race has to offer.", objectives = "Lok'lira the Crone in Brunnhildar Village wants you to defeat 6 Victorious Challengers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12972] = { id = 12972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You'll Need a Bear", description = "You've succeeded in the first rounds of the Hyldsmeet.  To advance further, you're going to need a warbear of your own.\n\nUnfortunately, the Hyldnir don't give them out to just anyone.  You'll have to emerge victorious from true battle, not just gladiatorial combat.\n\nThe Hyldnir of Brunnhildar are currently involved in a feud against the Sons of Hodir, Thorim's former allies.  Speak to Brijana just outside the village and see how you can help them and prove yourself in the process.", completion = "Think we'll give you your own bear just like that?  You'll have to prove yourself before you get anything from us.\n\nDo not think too highly of yourself just because you bested a few challengers in the Hyldsmeet.", objectives = "Speak to Brijana outside Brunnhildar Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12973] = { id = 12973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brothers Bronzebeard", description = "That does it! We finally have the keystone... It's beautiful! I've been around the world more than once, but this thing's got me all jittery with excitement again. I suppose now's not the time to stop and admire though, we need to get the heck out of here.\n\nHop on my flying machine and help keep us covered from those iron dwarves on the way out!", progress = "My pardons, lad! I got all caught up in tha moment and I neglected ye entirely.", completion = "King Stormheart sends his most sincere thanks for reuniting him with his brothers. It seems he's off to settle a score now - perhaps you'll meet with him again on Arthas's doorstep.", objectives = "Accompany Brann Bronzebeard and his flying machine to Frosthold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12974] = { id = 12974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Champion's Call!", description = "Pfft, what happens down here ain't fightin'. It's a couple of guys dancin' around a flag.\n\nYou lookin' for some real action, buddy? 'Cause if you are I got the hottest ticket in town.\n\nEver heard of Gurgthock and Wodin? Goblin and troll who ran the Ring of Blood back in Outland? Well they're here in Northrend and they've started up a whole new fight club over in Zul'Drak. If you're interested go to Zul'Drak, east of Crystalsong. They're at the big arena in the center. Tell 'em Shifty sent ya!", completion = "Shifty sent you, eh?", objectives = "Seek out Gurgthock at the Amphitheater of Anguish in Zul'Drak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12975] = { id = 12975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Memoriam", description = "Surely Thorim has told you of the tragedy that divides us.\n\nIt was in Thunderfall, northeast of here, that these events unfolded. The frozen fossils there are a reminder of that dark day, as are the spirits that haunt that place.\n\nIf my people are to forgive Thorim, something must take the place of those images. A memorial must be constructed to bring our hearts peace.\n\nGo there, {race}. Collect the fragments of Hodir's Horn that was shattered that day.", progress = "Have you found the pieces of Hodir's Horn?", completion = "Another good deed you have done on Thorim's behalf, {class}.\n\nThis will help to soften the hearts of my people towards him.", objectives = "King Jokkum in Dun Niffelem wants you to collect 8 Horn Fragments from Thunderfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12976] = { id = 12976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Monument to the Fallen", description = "Bring these fragments to Njormeld. He will use the pieces of that sacred relic in the construction of a mighty monument.\n\nMay it soothe the pains and heal the scars my people have borne these many years.\n\nMay its presence help to bring about a new age that sees us once again in glorious battle at Thorim's side.\n\nGo now, {class}. Njormeld awaits you.", progress = "You have brought the fragments of Hodir's Horn, {race}?", completion = "<Njormeld's eyes become noticeably moist as he pours the contents of the bag onto the anvil.>\n\nThe Horn of Hodir....\n\nThis was a sacred gift to our people from Hodir himself, {race}. It is a relic of great importance to us.\n\nWhen you next return to our stronghold you shall see the fruits of your labor.\n\nFarewell.", objectives = "King Jokkum wants you to bring Hodir's Horn Fragments to Njormeld in Dun Niffelem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12977] = { id = 12977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hodir's Call", description = "You have done a great service to the giants of Dun Niffelem. Without your aid, this monument would not exist.\n\nAs you silently ponder its significance, feelings begin to flood your heart. The feelings fill your mind with thoughts and images... as well as a sense of urgency.\n\nThe sensations fade and leave you with a knowledge of what you must do. The restless spirits at Thunderfall must be put to rest.\n\nAs you set off, you find that your hands have been filled with an ethereal horn.", completion = "You are filled with a sense of peace and contentment knowing that the once tormented souls of Thunderfall are now resting peacefully.", objectives = "Blow Hodir's Horn over 5 Niffelem Forefathers and 5 Restless Frostborn corpses at Thunderfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12978] = { id = 12978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Facing the Storm", description = "Like Bouldercrag, I once served the keepers as a craftsman in Ulduar, but with Loken's betrayal, I turned my hammer toward our new foes.\n\nWhen we could spare the men, I led raids on Nidavelir to relieve the pressure on our defenders, but our lines are near collapse.\n\nYou've proven yourself a capable combatant and a staunch ally. Perhaps you'd be willing to take up our banner and take the fight to Nidavelir, the iron dwarf stronghold to the southwest, across the Snowdrift Plains.", completion = "There may be hope for victory, {name}. We have never been able to sustain an attack on the stormforged, but with your efforts, Valduran may yet fall!", objectives = "Bruor Ironbane at Bouldercrag's Refuge wants you to kill 10 Nidavelir Stormforged. You may kill Stormforged Champions, Stormforged Magi, or Stormforged War Golems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12979] = { id = 12979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armor of Darkness", description = "This armor plate is thick and oversized compared to the rest of the golem's defenses. A quick examination of the golem's corpse reveals that this heavier plate seems to have been bolted on as an afterthought or a crude upgrade.\n\nWhy would the iron dwarves have added this redundant and mismatched armor to their war golems?\n\nPerhaps Bruor Ironbane would know if he had the chance to examine several of these plates from stormforged war golems.", progress = "What is it you have there?", completion = "Careful, now. Keep that plate as far away from me as you can. Even being in its presence is enough to inflict pain.\n\nBut you're right, {name}, these are gigantic armor plates for a war golem of normal size. What would the stormforged be doing with them? There's only one way to find out.", objectives = "Bring 4 Dark Armor Samples to Bruor Ironbane at Bouldercrag's Refuge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12980] = { id = 12980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Armor's Secrets", description = "The presence of that armor plate is disorienting, but we need to find out all we can from it. It could be part of one of Valduran's schemes.\n\nHe's dedicated an extraordinary amount of effort to mining, refining, smithing, and testing this metal.\n\nTo the east, along the northern mountain face, is a building called Mimir's Workshop. It hasn't been used in quite some time, but if we're lucky, some of its attendants are still functional. Take your armor plate there and learn what you can from it.", progress = "What did you learn?", completion = "<Bruor listens as you describe what you learned in the workshop.>\n\nSo Valduran's master has given him this sinister metal to construct a giant weapon? That must be what he intends to use for the final strike against us! We need to stop him before he's able to complete it and unleash this weapon.", objectives = "Take the Dark Armor Plate to Mimir's Workshop and ask Attendant Tock to examine it. When you're finished, return to Bruor Ironbane at Bouldercrag's Refuge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12981] = { id = 12981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hot and Cold", description = "As you stare at the anvil you relive your recent accomplishments, particularly those which brought this artifact to rest here.\n\nIt suddenly occurs to you that more remains to be done. To the east, smoldering scraps clutter the landscape--shrapnel from the battle fought there.\n\nIf they could be cooled and gathered somehow, the frost giants would have an abundant supply of metal and the region would be cleared of these remnants of war.", progress = "A luminous blue glow surrounds the anvil.", completion = "You feel a sense of accomplishment as you realize that your efforts continue to strengthen the renewed bonds between Thorim and the Sons of Hodir.", objectives = "You are to go to Frostfield Lake, kill the Brittle Revenants there and use the Essence of Ice on the Smoldering Scraps at Fjorn's Anvil. You are then to collect 6 of the Frozen Iron scraps and return to Fjorn's Anvil in Dun Niffelem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12982] = { id = 12982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ebon Blade Prisoners", description = "Now that I'm back, I'm certain that the baron will want me to recover my men. I can see that we're barely hanging on here. The Lich King's forces are about to break through and we won't be able to hold without my captured death knights.\n\nCan you assist me once more, {name}?\n\nGo back to Jotunheim and let them out of those cages. Break the damn locks, I don't care what you have to do. The vrykul likely have the keys.\n\nJust get my men free!", completion = "Thank you, {class}. With the death knights that you freed, we'll be able to hold the line... for now.", objectives = "Vaelen the Flayed at The Shadow Vault wants you to free 8 Ebon Blade Prisoners. They can be found in the cages throughout the greater Jotunheim region.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12983] = { id = 12983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last of Her Kind", description = "For as long as I can remember, we've obtained our best bears from the Hibernal Cave to the east.\n\nThose times might finally be gone.  The cave has been overrun by ravenous jormungar and the wild bears are all but extinct.\n\nIf you were to find a surviving matriarch, however, I would guarantee you that she would fight better than any of these bears born in captivity.\n\nTake this harness to the Hibernal Cave and rescue a surviving matriarch.  Good luck finding one.", completion = "I'm impressed.  I never thought I would see an icemaw matriarch again.  Especially not one this size.", objectives = "Astrid Bjornrittar in Brunnhildar Village wants you to rescue an Icemaw Matriarch in the Hibernal Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12984] = { id = 12984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valduran the Stormborn", description = "We have no choice, {name}. What you learned in Mimir's Workshop means that we must act before Valduran can complete and unleash his new weapon.\n\nEven now, the refuge's defenders fight to buy us time to deal with Valduran the Stormborn.\n\nYou must go to Nidavelir, across the Snowdrift Plains to the southwest, and then find and face Valduran. But you will not be alone. Bring this war horn with you and sound it as you prepare to face the leader of our enemies. Bruor and I will aid you in this battle.", completion = "At last, Valduran is dead, and the stormforged are weakened, but if his boasting is true, we must continue fighting the stormforged in his absence. This weapon they're building could be the end of us.", objectives = "Use Bouldercrag's War Horn when you have found Valduran the Stormborn. Defeat Valduran the Stormborn and return to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12985] = { id = 12985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging a Head", description = "Greetings, {race}.\n\nI have a task that King Jokkum felt you would be suited for, assuming you still strive to gain favor with our people.\n\nI have developed plans for another artifact, one that will grant Hodir's blessing of protection to our stronghold. I have nearly all that I require for its construction. All that remains to collect are the very eyes of our fallen enemies.\n\nTake this tool, and gather the eyes from the iron giant corpses that litter our fields.", progress = "Have you collected the final components I seek, {race}?", completion = "It is nearly done.\n\nWith this artifact in place, Dun Niffelem shall be warned of impending dangers before they are upon us.", objectives = "Njormeld in Dun Niffelem needs you to use the Diamond Tipped Pick on the Dead Iron Giants at Frostfield Lake and return to him when you have collected 8 Stormforged Eyes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
